// Verify X-Twilio-Signature.
//
// Algorithm (verified against Twilio's published test vector before this was
// written): HMAC-SHA1, base64, keyed with the account auth token, over the
// exact public webhook URL followed by every POST parameter sorted by name,
// name and value concatenated with NO delimiters.
//
// Iterates whatever parameters actually arrived. Never a fixed list: Twilio
// adds webhook parameters without notice, and validating against a hardcoded
// set silently starts rejecting valid requests.
const crypto = require('crypto');

// MUST be the exact public URL Twilio signed against. n8n sits behind Caddy and
// internally sees http://n8n:5678/..., which produces a different signature and
// a 403 on every request. Measured, not guessed. Constructed here rather than
// read from X-Forwarded-* so a forged header cannot influence what we verify.
const PUBLIC_URL = 'https://n8n.ryvodigital.com/webhook/twilio-inbound';

const item = $input.first().json;
const headers = item.headers || {};
const params = item.body || {};
const received = headers['x-twilio-signature'] || '';

const token = $env.TWILIO_AUTH_TOKEN;
const expectedSid = $env.TWILIO_ACCOUNT_SID;

function signatureBase(url, p) {
  const keys = Object.keys(p).sort();
  let s = url;
  for (const k of keys) {
    const v = p[k];
    s += k + (v === undefined || v === null ? '' : String(v));
  }
  return s;
}

let valid = false;
let reason = 'signature_mismatch';

if (!token) {
  reason = 'no_auth_token_in_env';
} else if (!received) {
  reason = 'missing_signature_header';
} else {
  const expected = crypto
    .createHmac('sha1', token)
    .update(Buffer.from(signatureBase(PUBLIC_URL, params), 'utf-8'))
    .digest('base64');
  const a = Buffer.from(expected, 'utf-8');
  const b = Buffer.from(received, 'utf-8');
  // Length check first: timingSafeEqual throws on length mismatch.
  if (a.length === b.length && crypto.timingSafeEqual(a, b)) {
    valid = true;
    reason = 'ok';
  }
}

// A valid signature proves the request came from *a* Twilio account. Confirm it
// is OURS before acting on it.
if (valid && expectedSid && params.AccountSid !== expectedSid) {
  valid = false;
  reason = 'account_sid_mismatch';
}

return [{ json: { headers, body: params, _sig: { valid, reason }, _startedAt: new Date().toISOString() } }];

// Normalise the Twilio payload into the shape the rest of the workflow uses.
// Everything downstream of here is channel-agnostic: swapping back to the Meta
// Cloud API should only require changing this node, the signature check and the
// eventual send node.
const src = $('VerifySignature').first().json;
const b = src.body || {};

// Twilio prefixes WhatsApp addresses: 'whatsapp:+351933048230'.
// leads.phone and clients.whatsapp_number store the bare E.164 number.
const strip = (v) => String(v || '').replace(/^whatsapp:/, '').trim();

const numMedia = parseInt(b.NumMedia || '0', 10) || 0;
const media = [];
for (let i = 0; i < numMedia; i++) {
  media.push({ url: b['MediaUrl' + i] || null, contentType: b['MediaContentType' + i] || null });
}

// A WhatsApp location arrives as Latitude/Longitude rather than as media, so
// NumMedia is 0 and it would otherwise look like an empty text message.
const lat = b.Latitude != null && b.Latitude !== '' ? Number(b.Latitude) : null;
const lon = b.Longitude != null && b.Longitude !== '' ? Number(b.Longitude) : null;
const hasLocation = Number.isFinite(lat) && Number.isFinite(lon);

// One label for what actually arrived, so the reply can suit it. A voice note
// is the case that matters most: it is a plausible way a real prospect sends
// their requirements, and answering it coldly loses them.
const types = media.map(m => String(m.contentType || '')).join(',');
let mediaKind = 'none';
if (hasLocation) mediaKind = 'location';
else if (/audio|ogg|voice|amr/i.test(types)) mediaKind = 'audio';
else if (/image/i.test(types)) mediaKind = 'image';
else if (/video/i.test(types)) mediaKind = 'video';
else if (/pdf|document|officedocument|msword/i.test(types)) mediaKind = 'document';
else if (numMedia > 0) mediaKind = 'other';

// What gets written to messages.body. The row must never be empty: a message
// nobody can see later is the same as a message that was dropped.
const KIND_LABEL = { audio: 'voice note', image: 'image', video: 'video',
                     document: 'document', location: 'location', other: 'attachment' };
const caption = String(b.Body || '').trim();
let storedBody = caption;
if (mediaKind !== 'none') {
  const label = '[' + (KIND_LABEL[mediaKind] || 'attachment')
    + (mediaKind === 'location' && hasLocation ? ': ' + lat.toFixed(5) + ',' + lon.toFixed(5) : '')
    + (numMedia > 1 ? ' x' + numMedia : '') + ']';
  storedBody = caption ? label + ' ' + caption : label;
}

return [{
  json: {
    // Supabase REST base. Not a secret -- the project URL is public by design;
    // access is gated by the service_role key (an encrypted n8n credential) and
    // by RLS being deny-by-default. Single place to change per environment.
    supabaseUrl: 'https://txxkqskhxhwtrhbmwwig.supabase.co',

    messageSid: b.MessageSid || null,
    accountSid: b.AccountSid || null,
    from: strip(b.From),
    to: strip(b.To),
    waId: b.WaId || null,
    profileName: b.ProfileName || null,
    body: b.Body || '',
    storedBody,
    caption,
    numMedia,
    media,
    mediaKind,
    latitude: lat, longitude: lon,
    locationLabel: b.Label || b.Address || null,
    // Checkpoint A only had to not crash on these; D3 answers them properly.
    // A caption alongside media is still non-text as far as routing goes: the
    // lead's real content is in the part we cannot read.
    isNonText: mediaKind !== 'none' || numMedia > 0,
    startedAt: src._startedAt,
  }
}];

// Flatten the client lookup and decide whether we know this recipient.
const res = $input.first().json;
const n = $('Normalise').first().json;
const rows = Array.isArray(res.body) ? res.body : [];
const client = rows[0] || null;
const ca = client && Array.isArray(client.client_automations) ? client.client_automations[0] : null;

// Supabase being unreachable (free-tier auto-pause) surfaces as a non-2xx or a
// transport error, NOT as an empty result. Distinguish the two: an empty list
// means 'we do not serve this number', a bad status means 'the platform DB is
// down'. Conflating them would silently drop real leads during an outage.
const httpOk = res.statusCode >= 200 && res.statusCode < 300;

return [{
  json: {
    ...n,
    httpOk,
    statusCode: res.statusCode,
    found: httpOk && !!client && !!ca,
    errorType: !httpOk ? 'platform_db_unreachable' : (!client || !ca ? 'unknown_client' : null),
    clientId: client ? client.id : null,
    clientName: client ? client.name : null,
    clientAutomationId: ca ? ca.id : null,
    config: ca ? ca.config : null,
  }
}];

// Carry forward whether this was a first contact, plus the lead id.
const up = $input.first().json;
const c = $('FlattenClient').first().json;
const prior = $('FindExistingLead').first().json;

const priorRows = Array.isArray(prior.body) ? prior.body : [];
const isNewLead = priorRows.length === 0;
// B3: has a human already taken this lead over? Read it BEFORE spending a
// Claude call, so an escalated lead is never answered again by the AI.
const priorQual = (priorRows[0] && priorRows[0].qualification) || {};
const escalatedAt = priorQual.escalated ? (priorQual.escalated.at || true) : null;
const rows = Array.isArray(up.body) ? up.body : [];
const lead = rows[0] || null;

return [{
  json: {
    ...c,
    isNewLead,
    leadId: lead ? lead.id : (priorRows[0] ? priorRows[0].id : null),
    upsertStatus: up.statusCode,
    alreadyEscalated: !!escalatedAt,
    escalatedAt,
    priorQualification: priorQual,
  }
}];

// ============================================================================
// Is there a property to view, or only a lead to meet? — shared source.
//
// Embedded verbatim into BuildClaudeRequest (which decides) and into
// ParseClaude / ParseGuardRetry (which check the reply). Unit-tested standalone
// in tests/appointment_kind.test.js, which loads THIS file rather than a copy.
//
// WHY THIS EXISTS
// On 2026-09-05 the Concierge sent a real lead:
//     "A sua visita esta confirmada para sexta-feira, dia 11 de setembro,
//      as 10:00, hora de Lisboa."
// The calendar half was correct: the slot was genuinely free, the event was
// created, the agent was notified. The CLAIM was not. Nobody -- not the lead,
// not an agent, not the Concierge -- had ever named a property. It booked a
// viewing of nothing, and the lead would have found out on the doorstep.
//
// engineering-lessons.md §0: never let a generated message narrate a future you
// have not secured. A property nobody has named is a future nobody has secured.
//
// THE RULE
// Unless a specific property has been named in the conversation, the
// appointment is a FIRST MEETING with an agent, and must be described as one.
// That is normal in this market and, unlike "visita", it is true. "visita" /
// "viewing" is reserved for when a property has a name.
//
// THE BIAS IS ONE-DIRECTIONAL, and deliberately so -- the same rule that
// governs matchConfirmation(). When in doubt it is a MEETING:
//   - calling a real viewing a meeting UNDER-describes an appointment that is
//     going to happen anyway. A human corrects it in one message.
//   - calling a meeting a viewing INVENTS a property. Nothing downstream can
//     correct that, because the lead has already been told.
// Every unknown below therefore resolves to 'meeting'.
//
// WHY NOT ASK THE MODEL
// Same reason the workflow picks the slots and the model only phrases them: the
// appointment kind decides what goes in a real agent's calendar and what a
// prospect is told. It has to be answerable from stored data. Asking the model
// "was a property discussed?" would make the guard depend on the judgement it
// exists to not trust.
// ============================================================================

// ---------------------------------------------------------------------------
// A listing reference is the only thing that counts as "a property has a name".
//
// An address or a house name ("a moradia na Rua das Flores") would need
// judgement to recognise, and judgement here means a model. So they are NOT
// detected, and such a conversation books a meeting. That is the safe
// direction and it is an honest under-description, not a wrong one.
//
// Two forms:
//   bare      A-1042, LX-2001            uppercase block, dash, 3-5 digits
//   keyword   Ref B-2001, referencia 10234, reference: LX88
// The bare form is case-SENSITIVE on purpose. Lowercase "t-3000" in prose is
// far more likely to be noise than a reference; a real one is written in caps
// or introduced by the word "ref".
// ---------------------------------------------------------------------------
const REF_BARE = /\b[A-Z]{1,3}-\d{3,5}\b/g;
const REF_KEYWORD =
  /\b(?:ref|refa|referencia|reference)\b\.?\s*[:#-]?\s*([A-Za-z]{0,4}-?\d{2,6}[A-Za-z]?)\b/gi;

function deaccent(s) {
  return String(s == null ? '' : s).normalize('NFD').replace(/[̀-ͯ]/g, '');
}

// findPropertyRefs(text) -> array of normalised reference strings (may be empty)
function findPropertyRefs(text) {
  const raw = String(text == null ? '' : text);
  if (!raw.trim()) return [];
  const found = [];
  const add = (v) => {
    const s = String(v).toUpperCase().replace(/\s+/g, '');
    if (s && found.indexOf(s) === -1) found.push(s);
  };

  // Bare form reads the ORIGINAL text: case is part of the signal.
  let m;
  REF_BARE.lastIndex = 0;
  while ((m = REF_BARE.exec(raw)) !== null) add(m[0]);

  // Keyword form reads the de-accented text so "referencia" and "referência"
  // are the same word.
  const flat = deaccent(raw);
  REF_KEYWORD.lastIndex = 0;
  while ((m = REF_KEYWORD.exec(flat)) !== null) add(m[1]);

  return found;
}

// ---------------------------------------------------------------------------
// appointmentKindFor(rows) -> {kind: 'viewing'|'meeting', refs: [...]}
//
// `rows` are message rows: {direction, body, ai_generated}.
//
// THE CONCIERGE'S OWN WORDS ARE NOT EVIDENCE. It has no inventory, so any
// reference it produced would be one it invented -- and trusting it would
// re-open exactly this defect one layer down. Outbound rows count only when
// they are explicitly marked as NOT ai_generated, which is a human agent
// replying from the cockpit (or a fixed config string, which never carries a
// reference). An outbound row whose origin cannot be established is ignored:
// if `ai_generated` is missing from the query, every conversation books a
// meeting, which is the fail-SAFE direction rather than the fail-open one.
// ---------------------------------------------------------------------------
function appointmentKindFor(rows) {
  const refs = [];
  for (const r of (Array.isArray(rows) ? rows : [])) {
    if (!r) continue;
    if (r.direction === 'outbound' && r.ai_generated !== false) continue;
    for (const ref of findPropertyRefs(r.body)) {
      if (refs.indexOf(ref) === -1) refs.push(ref);
    }
  }
  return { kind: refs.length ? 'viewing' : 'meeting', refs };
}

// ---------------------------------------------------------------------------
// viewingClaim(reply) -> the offending phrase, or null.
//
// The prompt tells the model which kind of appointment this is. This is the
// CHECK, not a better prompt -- §11 instance 11: when wording cannot hold a
// line reliably, replace it with something that fails loudly. The model wrote
// "a sua visita esta confirmada" under a prompt that already forbade asserting
// things it could not see.
//
// Applied only when the kind is 'meeting'. A rejection routes into the existing
// guard-retry; if the retry also claims a viewing, the turn escalates and NO
// booking is created -- a human holds a lead who is ready to book, which is a
// recoverable outcome, unlike the message this guard prevents.
//
// The list is not exhaustive and is not meant to be. It covers the words that
// NAME the appointment in the three languages the Concierge speaks. Paraphrases
// it misses are caught, if at all, by the prompt -- this is the backstop, and a
// backstop that tried to be complete would start rejecting honest sentences.
// ---------------------------------------------------------------------------
const VIEWING_WORDS = [
  // pt/es visita, visitas, visitar, visita-la; en visit, visits, visiting
  { rx: /\bvisit\w*/, label: 'visit*' },
  { rx: /\bviewings?\b/, label: 'viewing' },
  { rx: /\bview the\b/, label: 'view the' },
  { rx: /\bver (?:o|a|os|as|el|la|los|las) (?:imovel|imoveis|casa|moradia|apartamento|andar|vivienda|piso|propriedade|propiedad)\b/,
    label: 'ver o imovel' },
  { rx: /\bsee the (?:property|house|apartment|flat|villa)\b/, label: 'see the property' },
];

function viewingClaim(reply) {
  const t = deaccent(reply).toLowerCase();
  if (!t.trim()) return null;
  for (const w of VIEWING_WORDS) {
    const m = t.match(w.rx);
    if (m) return m[0];
  }
  return null;
}


// ============================================================================
// Who wrote what — shaping stored messages into the model's transcript.
//
// Embedded verbatim into BuildClaudeRequest. Unit-tested standalone in
// tests/transcript.test.js, which loads THIS file rather than a copy.
//
// WHY THIS EXISTS
// On 2026-09-11 a lead asked for a person, was escalated, got the fixed handoff
// note, was answered by a human from the cockpit, and was handed back to the
// AI. Their next message -- "Qual e o proximo passo?" -- was escalated again,
// with the reason "asked to speak to a person and asked about price
// negotiation". Neither was in that message. Both were earlier in the window.
//
// The model could not have done otherwise: the transcript it was given mapped
// EVERY outbound row to an assistant turn. The handoff note read as Sofia
// promising a colleague; the human's "hello" read as Sofia saying hello; and
// nothing anywhere said the earlier request had been dealt with. Read as a
// single unbroken conversation, the lead had asked for a person and nobody had
// come. Escalating again was the consistent answer to the wrong transcript.
//
// THE RULE
// Every row carries a durable `origin`, set by the node that wrote it. Rows the
// assistant did not write are labelled as such, in the turn itself, so the
// model does not inherit their tone or repeat their promises. A hand-back is
// stated as a note at the point in time it happened, so "already handled" is a
// fact in the transcript rather than something the model has to infer.
//
// `origin` is a COLUMN, not a body match against the configured strings. A
// client customising their handoff note must not silently turn every note back
// into Sofia's own words -- silent failure is this project's documented
// dominant risk. Rows written before the column existed were backfilled by
// migration 0010; the flag fallback below is for a row that somehow has none,
// and it resolves an unknown outbound row to 'system' (labelled as not yours),
// which is the fail-safe direction.
// ============================================================================

const ORIGINS = ['lead', 'ai', 'human', 'handoff', 'system'];

// originOf(row) -> 'lead' | 'ai' | 'human' | 'handoff' | 'system'
function originOf(r) {
  if (r && ORIGINS.indexOf(r.origin) !== -1) return r.origin;
  if (!r || r.direction === 'inbound') return 'lead';
  if (r.ai_generated === true) return 'ai';
  if (r.approved_by_human === true) return 'human';
  return 'system';
}

// The label is INSIDE the assistant turn. It has to travel with the words it
// describes; a note elsewhere in the prompt would have to be matched back to
// the right line by the model, which is the inference this file exists to
// remove.
const TURN_LABEL = {
  human:   '[Written by a human colleague from the agency, not by you. Their words and promises are theirs, not yours.]',
  handoff: '[Automatic handoff note, sent by the system when this conversation was passed to a human colleague. Not written by you.]',
  system:  '[Automatic system message, not written by you.]',
};

function whenUtc(iso) {
  const t = Date.parse(iso || '');
  if (!Number.isFinite(t)) return 'an earlier point';
  return new Date(t).toISOString().slice(0, 16).replace('T', ' ') + ' UTC';
}

function handBackNote(clearedAtIso) {
  return '[System note: at ' + whenUtc(clearedAtIso) + ' a human colleague finished '
    + 'handling this lead\'s earlier request and handed the conversation back to you. '
    + 'Everything above this note was dealt with by a person. Do not set needs_human '
    + 'again for anything above it; only what the lead says below this note can '
    + 'justify a new escalation.]';
}

// shapeTranscript(rows, opts) -> [{role, content}]
//
// `rows` are message rows, OLDEST FIRST:
//   {direction, body, ai_generated, approved_by_human, origin, created_at}
// `opts.escalationClearedAt` is the ISO time of the most recent hand-back, or
// null. The note is inserted before the first row after that time, and only
// when at least one row precedes it -- a hand-back older than the whole window
// has nothing left to close.
//
// Consecutive turns with the same role are merged, so the request never
// depends on the API accepting two assistant turns in a row. A labelled note
// followed by a human reply becomes one assistant turn with both labels.
function shapeTranscript(rows, opts) {
  const o = opts || {};
  const clearedAt = o.escalationClearedAt ? Date.parse(o.escalationClearedAt) : NaN;
  const turns = [];
  let noteDone = !Number.isFinite(clearedAt);
  let sawEarlier = false;

  for (const r of (Array.isArray(rows) ? rows : [])) {
    if (!r) continue;
    const body = String(r.body == null ? '' : r.body).trim();
    if (!body) continue;

    const t = Date.parse(r.created_at || '');
    if (!noteDone && Number.isFinite(t) && t > clearedAt) {
      if (sawEarlier) turns.push({ role: 'assistant', content: handBackNote(o.escalationClearedAt) });
      noteDone = true;
    }
    if (!noteDone && Number.isFinite(t) && t <= clearedAt) sawEarlier = true;

    const origin = originOf(r);
    if (origin === 'lead')    turns.push({ role: 'user', content: body });
    else if (origin === 'ai') turns.push({ role: 'assistant', content: body });
    else                      turns.push({ role: 'assistant', content: TURN_LABEL[origin] + '\n' + body });
  }

  const merged = [];
  for (const t of turns) {
    const last = merged[merged.length - 1];
    if (last && last.role === t.role) last.content += '\n\n' + t.content;
    else merged.push({ role: t.role, content: t.content });
  }
  // Anthropic requires the conversation to start with a user turn.
  while (merged.length && merged[0].role !== 'user') merged.shift();
  return merged;
}


const SYSTEM_TEMPLATE = "You are Sofia, an assistant for Ryvo Test Client, a luxury real estate agency covering Cascais, Estoril and Lisbon.\n\nLANGUAGE - THIS OVERRIDES EVERYTHING BELOW\nDetect the language of the lead's MOST RECENT message and reply in THAT language.\nEnglish in -> English out. Portugues in -> Portugues out. Espanol in -> Espanol out.\nIf the lead switches language mid-conversation, switch with them immediately.\nSome examples in these instructions are written in Portuguese purely to illustrate a\npattern; they are NOT a signal to reply in Portuguese. Never let the language of these\ninstructions influence the language of your reply - only the lead's message decides.\n\nVoice: warm, professional, never pushy. This is luxury real estate, not a call centre.\nKeep replies WhatsApp-native: 1-3 short sentences. No email formatting, no bullet lists, no headings.\nQualify conversationally, one or two questions at a time. Never interrogate with a list.\n\nOver the conversation, gather: buyer or seller, budget range, timeline, preferred area, financing status.\n\nYOU CANNOT SEE ANY PROPERTY LISTINGS\nYou have no access to listings, prices, availability, photos or stock of any kind.\nYou therefore must NEVER state or imply that a property exists, is available, or matches\nwhat the lead asked for. This includes soft implications. All of these are FORBIDDEN\n(shown in English and Portuguese only as examples - the rule applies in every language):\n  \"we have some options in that range\"    \"temos algumas opcoes\"\n  \"yes, we have sea-view apartments\"      \"sim, temos varios imoveis assim\"\n  \"there are a few that would suit you\"   \"encontramos facilmente algo assim\"\nEven a vague \"we do have options\" is forbidden, because you cannot know it.\n\nInstead, when asked what is available or whether something exists, do BOTH of these:\n  1. Say plainly that a colleague will confirm what is currently available.\n  2. Move the conversation forward with ONE qualifying question (area, budget, timeline,\n     bedrooms, or buy-to-live vs investment).\nDescribing which AREAS the agency covers is fine - that is not a stock claim.\n\nNOT KNOWING SOMETHING IS NORMAL - IT IS NOT AN ESCALATION\nSet needs_human FALSE when you simply lack a property detail. That is your most common\nsituation and you handle it yourself.\n\nWHAT YOU MUST NOT DO\n- Never invent property details, prices, availability, or legal/tax advice.\n- Never negotiate price or terms.\n- If asked directly whether you are an AI or a bot, say honestly that you are an assistant. Never claim to be human.\n- Never propose, invent, guess or calculate an appointment time yourself.\n\nBOOKING AN APPOINTMENT - YOU MAY OFFER TIMES, BUT ONLY OURS\nYou can now help book appointments. The system checks the real calendar and supplies\nthe available times. Your job is to phrase the offer warmly - never to choose it.\n\nWHAT KIND OF APPOINTMENT IT IS - THE SYSTEM DECIDES THIS, NOT YOU\nYou are told APPOINTMENT: meeting or APPOINTMENT: viewing. Follow it exactly.\n- meeting: a first meeting with one of our agents. NO specific property has been\n  named by anyone in this conversation, so there is nothing to view. Call it a\n  meeting, a conversation or a chat with a colleague - for example \"uma primeira\n  reuniao com o nosso colega\". NEVER call it a visita, a visit, a viewing, or\n  seeing/ver the property: that promises a property this conversation does not\n  have. A first appointment being a conversation with an agent is completely\n  normal in this market. Say it warmly and plainly, never as a downgrade, never\n  as an apology, and never as a substitute for something better.\n- viewing: a specific property HAS been named in this conversation, so a viewing\n  is what it is and you may call it one. But a property having a NAME is not the\n  same as a property being AVAILABLE. You still cannot see listings, so you do\n  not know that it exists, that it is still on the market, or that it did not go\n  under offer last week. Never say or imply that we can show it, that it is\n  available, or that it is still for sale. Two things are true at once and you\n  must say both: the TIME is ours to confirm, and a colleague will confirm the\n  PROPERTY itself before the appointment. \"Agendamos uma visita ao X\" on its own\n  is a stock claim - it promises a house we have not checked.\nNever upgrade a meeting to a viewing, not even when the lead calls it one. If the\nlead writes \"queria visitar\", you are still booking a meeting with an agent\nunless you were told otherwise - be warm, and describe what is actually booked.\n\n- If AVAILABLE_SLOTS is given to you, offer those times and ONLY those times.\n  Do not round them, shift them, re-describe them vaguely as \"around 3pm\", add a\n  slot, or suggest any alternative time that is not on the list.\n- Always state the timezone exactly as given (for example \"15:00 Lisbon time\"),\n  even if the lead appears to be somewhere else.\n- If AVAILABLE_SLOTS is empty or absent, say honestly that you will check\n  availability and come back to them. Do NOT name any time at all.\n- If the lead asks to change or cancel an appointment that is already booked, do\n  not attempt it - set needs_human true.\n- A BOOKING note states what the system has ALREADY done. It is fact, not a\n  suggestion: follow it exactly. NEVER tell a lead an appointment is booked unless\n  the CURRENT BOOKING note says it is. Claiming a booking that does not exist is\n  worse than inventing a time - the lead will turn up and nobody will be there.\n- The BOOKING note outranks the conversation, including your own earlier\n  messages. If it says the lead has NO appointment booked, then none is booked -\n  even if you confirmed one further up. Appointments get cancelled after they are\n  confirmed, and the note is the only place you learn that. Never say \"ja tem\n  uma reuniao marcada\" or \"your meeting is set for\" on the strength of history.\n\nThis is the same rule as property inventory: you may state what the system knows,\nand must never assert what you cannot see. A time you invent is an appointment the\nagent will not attend. A property you imply is one the lead will not be shown.\n\nThe AVAILABLE_SLOTS list is written in English for the system's convenience. It\nis NOT a signal about which language to reply in. Dates and times are DATA to be\nrestated in the lead's own language - translate the weekday and month names, keep\nthe numbers and the timezone label exactly as given.\n\nSET needs_human TRUE ONLY FOR THESE\n- The lead explicitly asks to speak to a person.\n- Price negotiation, offers, or contractual/legal/tax questions.\n- The lead is upset, complaining, or hostile.\n- The lead wants to move, change or cancel an appointment that is already booked.\n- Anything you genuinely cannot handle without inventing facts BEYOND ordinary \"I don't have that detail\".\n\nWHO WROTE WHAT\nSome assistant-side turns in the conversation start with a label in square brackets:\na message written by a human colleague from the agency, an automatic handoff note\nsent by the system, or a system note saying a colleague has handed the conversation\nback to you. Those words are NOT yours. Do not carry on their tone, and do not repeat\ntheir promises - if a note already told the lead a colleague will be in touch, you do\nnot say it again.\n\nALREADY HANDLED BY A COLLEAGUE - DO NOT ESCALATE IT TWICE\nAn escalation can build over several messages - growing frustration, or a price\nquestion that develops - so read the conversation, not only the last line. But a\nrequest a human colleague has already dealt with is closed. After a hand-back note,\nor after a human colleague's own reply, do NOT set needs_human for anything the lead\nsaid before that point. Only what the lead has said since then can justify a new\nescalation. A lead who asked for a person, was answered by one, and is now simply\ncontinuing the conversation has not asked for a person again.\n\nescalation_reason: when needs_human is true, describe ONLY the lead's own words that\ntrigger it now, quoting or closely paraphrasing them. Never cite anything from before a\nhand-back, and never attribute to the lead something they did not say in this\nconversation. When needs_human is false, escalation_reason is null.\n\nIf needs_human is true, your reply must still be warm and must not promise a specific time or outcome.\n";
const REPLY_SCHEMA = {"type": "object", "properties": {"reply": {"type": "string"}, "lead_type": {"type": "string", "enum": ["buyer", "seller", "renter", "unknown"]}, "full_name": {"type": ["string", "null"]}, "budget_min": {"type": ["number", "null"]}, "budget_max": {"type": ["number", "null"]}, "timeline": {"type": ["string", "null"]}, "area": {"type": ["string", "null"]}, "qualification_notes": {"type": "object", "properties": {"financing": {"type": ["string", "null"]}, "bedrooms": {"type": ["number", "null"]}, "purpose": {"type": ["string", "null"]}}, "required": ["financing", "bedrooms", "purpose"], "additionalProperties": false}, "stage": {"type": "string", "enum": ["contacted", "qualified", "nurturing"]}, "intent": {"type": "string", "enum": ["question", "booking", "not_interested", "other"]}, "wants_booking": {"type": "boolean"}, "proposed_times": {"type": "array", "items": {"type": "string"}}, "needs_human": {"type": "boolean"}, "escalation_reason": {"type": ["string", "null"]}}, "required": ["reply", "lead_type", "full_name", "budget_min", "budget_max", "timeline", "area", "qualification_notes", "stage", "intent", "wants_booking", "proposed_times", "needs_human", "escalation_reason"], "additionalProperties": false};

// Build the Anthropic request. Everything tunable comes from
// client_automations.config so model/effort are a config change, not a node edit.
const a   = $('AfterLead').first().json;
const cfg = a.config || {};
const res = $('LoadHistory').first().json;
// Read by name, not $input: the item may arrive via EventBookingCheck, whose
// output is an HTTP response envelope, not the booking state.
const sl  = $('ResolveBooking').first().json;
const mc  = sl;

// A failed history query and a genuinely-first message are different situations.
// Only one of them is normal. Distinguish them rather than proceeding blind.
const httpOk = res.statusCode >= 200 && res.statusCode < 300;
if (!httpOk) {
  return [{ json: { ...a, fatal: true, errorType: 'history_load_failed',
                    errorMessage: 'messages query returned ' + res.statusCode } }];
}

const rows = Array.isArray(res.body) ? res.body : [];
// Query is newest-first so the LIMIT takes the LAST N. Reverse for oldest-first.
const ordered = rows.slice().reverse();

// Checkpoint A already stored this inbound message, so it IS the final user turn.
// Verify that empirically instead of reasoning about it.
const last = ordered[ordered.length - 1];
const currentTurnAlreadyPresent = !!last && last.external_id === a.messageSid;

// Who wrote what is stated IN the transcript -- handoff notes and human
// replies are labelled as not the assistant's, and a hand-back is a note at the
// point it happened. See the header of src/transcript.js for the 2026-09-11
// re-escalation this prevents.
const pq = a.priorQualification || {};
const escalationClearedAt = pq.escalation_cleared_at || null;
const messages = shapeTranscript(ordered, { escalationClearedAt });

if (!currentTurnAlreadyPresent) {
  // Defensive: if A's row is somehow missing, append the live text rather than
  // calling with no current turn at all.
  const lastTurn = messages[messages.length - 1];
  if (lastTurn && lastTurn.role === 'user') lastTurn.content += '\n\n' + a.body;
  else messages.push({ role: 'user', content: a.body });
}
if (!messages.length) {
  return [{ json: { ...a, fatal: true, errorType: 'empty_history',
                    errorMessage: 'no usable messages to send' } }];
}

// ---------------------------------------------------------------------------
// Is there a property to view, or only a lead to meet? Decided HERE, from the
// stored conversation, before the model writes a word -- the same reason the
// workflow picks the slots rather than asking for them. See the header of
// src/appointment_kind.js for the defect this exists to prevent.
//
// The current inbound message is included: a lead who opens with "quero ver o
// B-2001" has named a property on the very turn they are asking about.
// ---------------------------------------------------------------------------
const historyRows = ordered.concat(
  currentTurnAlreadyPresent ? [] : [{ direction: 'inbound', body: a.body, ai_generated: false }]);
const ak = appointmentKindFor(historyRows);
const appointmentKind = ak.kind;
const propertyRefs = ak.refs;

const areas = (cfg.areas || []).join(', ');
let system = SYSTEM_TEMPLATE
  .replace(/__AGENT__/g, cfg.agent_name || 'Sofia')
  .replace(/__AGENCY__/g, cfg.agency_name || a.clientName || 'the agency')
  .replace(/__AREAS__/g, areas || 'the areas we cover');

// Availability is appended LAST. The reminder about language sits with it,
// because an English slot list leaked into the reply language 1 time in 12
// until it did (see engineering-lessons.md §4).
if ((sl.slotLines || []).length) {
  system += '\n\nAVAILABLE_SLOTS (offer only these, exactly as written; only if the lead is asking to book or view):\n'
          + sl.slotLines.map(l => '- ' + l).join('\n');
  // Each status is a different sentence to the lead. "Fully booked" was being
  // said about a day that was merely inside our notice period -- an assertion
  // about the calendar that nothing had checked.
  const WHY = {
    full:          'is fully booked',
    too_soon:      'is too soon - we need at least ' + (cfg.min_hours_notice == null ? 24 : cfg.min_hours_notice) + ' hours notice',
    closed_day:    'is not a day we do viewings',
    out_of_window: 'is further ahead than we can book right now',
  };
  if (sl.preferRequested && WHY[sl.preferStatus]) {
    system += '\n\nNOTE: the lead asked about ' + sl.preferRequested + ', and that day '
            + WHY[sl.preferStatus] + '. Say that plainly, in their language, before '
            + 'offering the times above. Do not guess at any other reason.';
  }
  system += '\n\nREMINDER: reply in the language of the lead\'s most recent message. '
          + 'The list above is in English only because the system wrote it. Translate '
          + 'weekday and month names; keep the numbers and the timezone label exactly as given.';
} else {
  system += '\n\nAVAILABLE_SLOTS: none available. If the lead asks to book, say honestly '
          + 'that you will check availability and come back to them. Do NOT name any time.';
}

// The appointment kind is a FACT the workflow established, in the same class as
// the slot list: stated to the model, never asked of it.
system += '\n\nAPPOINTMENT: ' + appointmentKind
        + (appointmentKind === 'viewing'
             ? ' (the lead has named a property in this conversation: '
               + propertyRefs.join(', ') + '. That is THEIR reference, not a '
               + 'confirmation from us - nothing has checked that it exists or is '
               + 'still available, so confirm the time and say a colleague will '
               + 'confirm the property itself.)'
             : ' (no specific property has been named by anyone in this conversation, '
               + 'so there is nothing to view - this is a first meeting with an agent)');

// --- what the workflow already did about booking, stated as fact -------------
// The model is TOLD the outcome, never asked for it. By the time it writes, the
// event either exists or it does not, so it cannot confirm a booking that
// failed -- and it cannot invent one that never happened.
const fmt = (s) => {
  const zone = s.zone || cfg.timezone || 'Europe/Lisbon';
  const dt = DateTime.fromISO(s.startUtc).setZone(zone);
  return dt.toFormat('cccc d LLLL yyyy') + ' at ' + dt.toFormat('HH:mm') + ' '
       + zone.split('/')[1].replace('_', ' ') + ' time';
};
const NOUN = appointmentKind === 'viewing'
  ? 'viewing of the property the lead named (whose availability we have NOT '
    + 'checked - confirm the time, and say a colleague confirms the property)'
  : 'first meeting with one of our agents (NOT a viewing - no property has been named)';
if (mc.bookingIntent === 'confirm' && mc.bookingSlot) {
  system += '\n\nBOOKING: the lead has just accepted ' + fmt(mc.bookingSlot)
          + '. It has been checked as free and is being booked now, as a ' + NOUN + '. '
          + 'Confirm it warmly, call it what it is, and restate the day, date, time and '
          + 'timezone exactly. Do NOT offer any other time, and do NOT say you will '
          + 'check with a colleague.';
} else if (mc.bookingIntent === 'taken' && mc.bookingSlot) {
  system += '\n\nBOOKING: the time the lead just chose was taken in the last few minutes. '
          + 'Apologise plainly, say it has just gone, and offer the times listed above.';
} else if (mc.bookingIntent === 'ambiguous') {
  system += '\n\nBOOKING: the lead seems to be accepting, but it is not clear which time. '
          + 'Ask which one, repeating the options above. Do NOT confirm anything yet.';
} else if (mc.bookingIntent === 'offer_stale') {
  system += '\n\nBOOKING: the times we offered this lead are more than a day old, so they '
          + 'are no longer reliable. Do not treat their reply as a confirmation. Offer the '
          + 'current times listed above instead.';
} else if (mc.bookingIntent === 'already_booked' && mc.existingBooking) {
  // Verified against the calendar by ResolveBooking this turn, or -- when the
  // calendar could not be read -- kept and said so. Never asserted unchecked.
  system += '\n\nBOOKING: this lead ALREADY has a ' + NOUN + ' booked for '
          + fmt(mc.existingBooking) + '. Do not book another one and do not offer times. '
          + 'If they are asking to move, change or cancel it, set needs_human true - '
          + 'a colleague handles changes to a booked viewing.'
          + (mc.bookingUnreadable
               ? ' (The calendar could not be checked just now; this is what was last recorded.)'
               : '');
} else if (mc.bookingRetired && (mc.bookingCheck === 'cancelled' || mc.bookingCheck === 'missing')) {
  // The stored booking was withdrawn this turn: the event is no longer in the
  // calendar. The lead may not know. Say what is true, promise nothing about
  // why, and let them choose a new time from the real list.
  system += '\n\nBOOKING: an appointment previously booked for ' + fmt(mc.bookingRetired)
          + ' is NO LONGER in the calendar - it was removed on our side. Do NOT describe it '
          + 'as booked or confirmed, and do not guess why it was removed. If the lead refers '
          + 'to it, say plainly that it is no longer in the diary and that a colleague will be '
          + 'in touch about it. If they would like a new time, offer the times listed above; '
          + 'if none are listed, say you will check and come back to them.';
} else if (mc.bookingRetired && mc.bookingCheck === 'past') {
  system += '\n\nBOOKING: the appointment booked for ' + fmt(mc.bookingRetired)
          + ' has already taken place, or its time has passed. Do not describe it as '
          + 'upcoming and do not confirm it again. If the lead wants another appointment, '
          + 'offer the times listed above.';
}

// ---------------------------------------------------------------------------
// The ABSENCE of a booking is stated every turn. On 2026-09-12 a lead whose
// booking had been retired was told "ja tem uma reuniao marcada" -- the model
// read its own confirmation twenty lines up and nothing in the prompt said
// otherwise, because notes were only written when a booking existed or had
// been retired that very turn. A fact the workflow holds is stated on every
// turn it holds it; the retired booking is named so the model has something to
// set against its own history. bookingClaim() in the parsers is the backstop;
// THIS is the fix.
// ---------------------------------------------------------------------------
const holdsBooking = mc.bookingIntent === 'already_booked' && !!mc.existingBooking;
const creatingBooking = mc.bookingIntent === 'confirm' && !!mc.bookingSlot;
if (!holdsBooking && !creatingBooking) {
  system += '\n\nBOOKING STATUS: this lead has NO appointment booked at the moment. This '
          + 'outranks everything in the conversation above, including any earlier message '
          + 'of yours that confirmed a time - that appointment no longer stands. Do not say '
          + 'or imply that anything is booked, and do not offer to "keep" or "change" an '
          + 'existing appointment. If they want one, offer the times listed above.';
  const past = Array.isArray(pq.past_bookings) ? pq.past_bookings : [];
  const lastPast = past.length ? past[past.length - 1] : null;
  if (lastPast && lastPast.startUtc) {
    const WHY = { cancelled: 'was removed from the calendar on our side',
                  missing:   'is no longer in the calendar',
                  past:      'has already taken place, or its time has passed' };
    system += ' An earlier appointment for ' + fmt(lastPast) + ' '
            + (WHY[lastPast.retired_reason] || 'no longer stands')
            + '. If the lead refers to it, say plainly that it is no longer in the diary and '
            + 'that a colleague will be in touch about it; do not guess why, and do not '
            + 'describe it as booked.';
  }
}

return [{ json: {
  ...a,
  fatal: false,
  currentTurnAlreadyPresent,
  historyCount: messages.length,
  escalationClearedAt,
  claudeBody: {
    model: cfg.model || 'claude-sonnet-5',
    max_tokens: cfg.max_tokens || 1024,
    system,
    messages,
    thinking: { type: cfg.thinking || 'adaptive' },
    output_config: { effort: cfg.effort || 'low',
                     format: { type: 'json_schema', schema: REPLY_SCHEMA } },
  },
  claudeStartedAt: new Date().toISOString(),
  slots: sl.slots || [],
  slotLines: sl.slotLines || [],
  slotError: sl.slotError || null,
  preferDate: sl.preferDate || null,
  preferStatus: sl.preferStatus || 'none',
  preferRequested: sl.preferRequested || null,
  bookingIntent: sl.bookingIntent || 'none',
  bookingSlot: sl.bookingSlot || null,
  // ParseClaude allows a reply to restate a booked time only if it can see the
  // booking; this was missing, so a restated time was rejected as invented.
  existingBooking: sl.existingBooking || null,
  bookingCheck: sl.bookingCheck || 'none',
  bookingRetired: sl.bookingRetired || null,
  bookingUnreadable: !!sl.bookingUnreadable,
  bookingCheckStatus: sl.bookingCheckStatus == null ? null : sl.bookingCheckStatus,
  bookingCheckError: sl.bookingCheckError || null,
  appointmentKind,
  propertyRefs,
} }];

// ============================================================================
// Is there a property to view, or only a lead to meet? — shared source.
//
// Embedded verbatim into BuildClaudeRequest (which decides) and into
// ParseClaude / ParseGuardRetry (which check the reply). Unit-tested standalone
// in tests/appointment_kind.test.js, which loads THIS file rather than a copy.
//
// WHY THIS EXISTS
// On 2026-09-05 the Concierge sent a real lead:
//     "A sua visita esta confirmada para sexta-feira, dia 11 de setembro,
//      as 10:00, hora de Lisboa."
// The calendar half was correct: the slot was genuinely free, the event was
// created, the agent was notified. The CLAIM was not. Nobody -- not the lead,
// not an agent, not the Concierge -- had ever named a property. It booked a
// viewing of nothing, and the lead would have found out on the doorstep.
//
// engineering-lessons.md §0: never let a generated message narrate a future you
// have not secured. A property nobody has named is a future nobody has secured.
//
// THE RULE
// Unless a specific property has been named in the conversation, the
// appointment is a FIRST MEETING with an agent, and must be described as one.
// That is normal in this market and, unlike "visita", it is true. "visita" /
// "viewing" is reserved for when a property has a name.
//
// THE BIAS IS ONE-DIRECTIONAL, and deliberately so -- the same rule that
// governs matchConfirmation(). When in doubt it is a MEETING:
//   - calling a real viewing a meeting UNDER-describes an appointment that is
//     going to happen anyway. A human corrects it in one message.
//   - calling a meeting a viewing INVENTS a property. Nothing downstream can
//     correct that, because the lead has already been told.
// Every unknown below therefore resolves to 'meeting'.
//
// WHY NOT ASK THE MODEL
// Same reason the workflow picks the slots and the model only phrases them: the
// appointment kind decides what goes in a real agent's calendar and what a
// prospect is told. It has to be answerable from stored data. Asking the model
// "was a property discussed?" would make the guard depend on the judgement it
// exists to not trust.
// ============================================================================

// ---------------------------------------------------------------------------
// A listing reference is the only thing that counts as "a property has a name".
//
// An address or a house name ("a moradia na Rua das Flores") would need
// judgement to recognise, and judgement here means a model. So they are NOT
// detected, and such a conversation books a meeting. That is the safe
// direction and it is an honest under-description, not a wrong one.
//
// Two forms:
//   bare      A-1042, LX-2001            uppercase block, dash, 3-5 digits
//   keyword   Ref B-2001, referencia 10234, reference: LX88
// The bare form is case-SENSITIVE on purpose. Lowercase "t-3000" in prose is
// far more likely to be noise than a reference; a real one is written in caps
// or introduced by the word "ref".
// ---------------------------------------------------------------------------
const REF_BARE = /\b[A-Z]{1,3}-\d{3,5}\b/g;
const REF_KEYWORD =
  /\b(?:ref|refa|referencia|reference)\b\.?\s*[:#-]?\s*([A-Za-z]{0,4}-?\d{2,6}[A-Za-z]?)\b/gi;

function deaccent(s) {
  return String(s == null ? '' : s).normalize('NFD').replace(/[̀-ͯ]/g, '');
}

// findPropertyRefs(text) -> array of normalised reference strings (may be empty)
function findPropertyRefs(text) {
  const raw = String(text == null ? '' : text);
  if (!raw.trim()) return [];
  const found = [];
  const add = (v) => {
    const s = String(v).toUpperCase().replace(/\s+/g, '');
    if (s && found.indexOf(s) === -1) found.push(s);
  };

  // Bare form reads the ORIGINAL text: case is part of the signal.
  let m;
  REF_BARE.lastIndex = 0;
  while ((m = REF_BARE.exec(raw)) !== null) add(m[0]);

  // Keyword form reads the de-accented text so "referencia" and "referência"
  // are the same word.
  const flat = deaccent(raw);
  REF_KEYWORD.lastIndex = 0;
  while ((m = REF_KEYWORD.exec(flat)) !== null) add(m[1]);

  return found;
}

// ---------------------------------------------------------------------------
// appointmentKindFor(rows) -> {kind: 'viewing'|'meeting', refs: [...]}
//
// `rows` are message rows: {direction, body, ai_generated}.
//
// THE CONCIERGE'S OWN WORDS ARE NOT EVIDENCE. It has no inventory, so any
// reference it produced would be one it invented -- and trusting it would
// re-open exactly this defect one layer down. Outbound rows count only when
// they are explicitly marked as NOT ai_generated, which is a human agent
// replying from the cockpit (or a fixed config string, which never carries a
// reference). An outbound row whose origin cannot be established is ignored:
// if `ai_generated` is missing from the query, every conversation books a
// meeting, which is the fail-SAFE direction rather than the fail-open one.
// ---------------------------------------------------------------------------
function appointmentKindFor(rows) {
  const refs = [];
  for (const r of (Array.isArray(rows) ? rows : [])) {
    if (!r) continue;
    if (r.direction === 'outbound' && r.ai_generated !== false) continue;
    for (const ref of findPropertyRefs(r.body)) {
      if (refs.indexOf(ref) === -1) refs.push(ref);
    }
  }
  return { kind: refs.length ? 'viewing' : 'meeting', refs };
}

// ---------------------------------------------------------------------------
// viewingClaim(reply) -> the offending phrase, or null.
//
// The prompt tells the model which kind of appointment this is. This is the
// CHECK, not a better prompt -- §11 instance 11: when wording cannot hold a
// line reliably, replace it with something that fails loudly. The model wrote
// "a sua visita esta confirmada" under a prompt that already forbade asserting
// things it could not see.
//
// Applied only when the kind is 'meeting'. A rejection routes into the existing
// guard-retry; if the retry also claims a viewing, the turn escalates and NO
// booking is created -- a human holds a lead who is ready to book, which is a
// recoverable outcome, unlike the message this guard prevents.
//
// The list is not exhaustive and is not meant to be. It covers the words that
// NAME the appointment in the three languages the Concierge speaks. Paraphrases
// it misses are caught, if at all, by the prompt -- this is the backstop, and a
// backstop that tried to be complete would start rejecting honest sentences.
// ---------------------------------------------------------------------------
const VIEWING_WORDS = [
  // pt/es visita, visitas, visitar, visita-la; en visit, visits, visiting
  { rx: /\bvisit\w*/, label: 'visit*' },
  { rx: /\bviewings?\b/, label: 'viewing' },
  { rx: /\bview the\b/, label: 'view the' },
  { rx: /\bver (?:o|a|os|as|el|la|los|las) (?:imovel|imoveis|casa|moradia|apartamento|andar|vivienda|piso|propriedade|propiedad)\b/,
    label: 'ver o imovel' },
  { rx: /\bsee the (?:property|house|apartment|flat|villa)\b/, label: 'see the property' },
];

function viewingClaim(reply) {
  const t = deaccent(reply).toLowerCase();
  if (!t.trim()) return null;
  for (const w of VIEWING_WORDS) {
    const m = t.match(w.rx);
    if (m) return m[0];
  }
  return null;
}


// ============================================================================
// Does the reply assert an appointment the workflow does not hold? — shared
// source. Embedded verbatim into ParseClaude and ParseGuardRetry. Unit-tested
// standalone in tests/booking_claim.test.js, which loads THIS file.
//
// WHY THIS EXISTS
// On 2026-09-12 a lead whose booking had been retired asked for a meeting and
// was told "Ja tem uma reuniao marcada para terca-feira, dia 15 ... as 09:00".
// The workflow held no booking. The model read its own confirmation twenty
// lines up the transcript and repeated it. The time was on the offered list,
// so the invented-time guard passed; "reuniao" is not "visita", so the
// viewing-claim guard passed. Nothing checked the claim itself.
//
// SECOND LINE OF DEFENCE, NOT THE FIRST
// The prompt now states the absence of a booking every turn, with the retired
// one named. That is the fix. Phrase matching across three languages will miss
// paraphrases -- "a reuniao fica entao para terca" is an assertion that no
// short list anticipates completely -- so this guard exists to fail loudly on
// the common shapes, never to justify a weaker prompt. Same posture as
// viewingClaim: a backstop that tried to be complete would start rejecting
// honest sentences.
//
// SHAPE
// Statements only: a sentence ending in "?" is an offer or a question, never
// an assertion, so it is skipped. Negations ("ja nao esta marcada", "is no
// longer in the diary") do not match by construction -- every pattern needs
// the affirmative form. Applied ONLY when the workflow holds no booking and is
// not creating one this turn; an honest confirmation is never tested.
// ============================================================================

function deaccentClaim(s) {
  return String(s == null ? '' : s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
}

const BOOKING_CLAIMS = [
  // --- pt ------------------------------------------------------------------
  // "ja tem uma reuniao marcada", "ja esta confirmada", "ja fica agendada"
  { rx: /\bja (?:tem|temos|esta|fica|ficou) [^.!?\n]{0,40}?(?:marcad|confirmad|agendad|reuniao|visita)/, label: 'ja tem ... marcada' },
  // "a reuniao fica entao para terca", "a sua visita esta marcada", "a reuniao continua para"
  { rx: /\b(?:reuniao|visita|marcacao|conversa|encontro) (?:fica|esta|ficou|continua|mantem-se) (?:entao |assim |portanto |sempre )?(?:marcad|confirmad|agendad|para\b|na\b|no\b|as\b)/, label: 'a reuniao fica para' },
  // "esta marcada para terca-feira", "ficou confirmada para dia 15"
  { rx: /\b(?:esta|ficou|fica|estao|ficam) (?:entao |assim )?(?:marcad[ao]s?|confirmad[ao]s?|agendad[ao]s?) para (?:o |a |as |os |o dia |dia |segunda|terca|quarta|quinta|sexta|sabado|domingo|\d)/, label: 'esta marcada para <dia>' },
  // "temos a reuniao marcada", "mantemos a visita marcada"
  { rx: /\b(?:temos|mantemos) (?:a |uma |essa |esta )?(?:reuniao|visita|marcacao|conversa) (?:marcad|confirmad|agendad)/, label: 'temos a reuniao marcada' },
  // --- es ------------------------------------------------------------------
  { rx: /\bya (?:tiene|tenemos|esta|queda) [^.!?\n]{0,40}?(?:cita|reunion|visita|confirmad|agendad|reservad|programad)/, label: 'ya tiene ... cita' },
  { rx: /\b(?:cita|reunion|visita) (?:queda|esta|sigue|se mantiene) (?:entonces )?(?:confirmad|agendad|reservad|programad|para\b|el\b|la\b|los\b|las\b)/, label: 'la cita queda para' },
  { rx: /\b(?:esta|queda|quedo|quedan) (?:entonces )?(?:confirmad[ao]s?|agendad[ao]s?|reservad[ao]s?|programad[ao]s?) para (?:el |la |las |los |lunes|martes|miercoles|jueves|viernes|sabado|domingo|\d)/, label: 'queda confirmada para <dia>' },
  // --- en ------------------------------------------------------------------
  { rx: /\byou(?:'re| are)? already (?:have|booked|down|set|confirmed)\b/, label: 'you already have' },
  { rx: /\b(?:your|the) (?:meeting|viewing|appointment|call) (?:is|remains|stays|is still) (?:set |booked |confirmed |scheduled |in the diary |on )?(?:for|on|at)\b/, label: 'your meeting is for' },
  { rx: /\b(?:is|are|remains|stays) (?:already |still |now )?(?:booked|confirmed|scheduled|in the diary) for (?:the |mon|tue|wed|thu|fri|sat|sun|\d|next|this|tomorrow)/, label: 'is booked for <day>' },
  { rx: /\bwe have you (?:booked|down) for\b/, label: 'we have you booked for' },
  { rx: /\bi(?:'ve| have) (?:got )?you (?:booked|down) for\b/, label: 'I have you booked for' },
];

// bookingClaim(reply) -> the offending phrase (label), or null.
function bookingClaim(reply) {
  const raw = String(reply == null ? '' : reply);
  if (!raw.trim()) return null;
  // Sentence by sentence, so a question is never read as an assertion.
  const sentences = raw.split(/(?<=[.!?\n])\s+|\n+/);
  for (const sentence of sentences) {
    const s = sentence.trim();
    if (!s || s.endsWith('?')) continue;
    const t = deaccentClaim(s);
    for (const c of BOOKING_CLAIMS) {
      const m = t.match(c.rx);
      if (m) return m[0];
    }
  }
  return null;
}



// Defensive parse. Structured outputs (output_config.format) already constrain the
// response to the schema at the API level, so this is a BACKSTOP, not the primary
// mechanism - but it is not dead code: structured outputs do NOT hold when
// stop_reason is 'refusal' or 'max_tokens'.
const b   = $('BuildClaudeRequest').first().json;
const res = $input.first().json;
const started = b.claudeStartedAt;
const finished = new Date().toISOString();
const durationMs = Math.max(0, new Date(finished) - new Date(started));

function fail(errorType, errorMessage) {
  return [{ json: { ...b, ok: false, errorType, errorMessage, durationMs,
                    usage: null, parsed: null } }];
}

const code = res.statusCode;
if (code === 401 || code === 403) return fail('claude_auth', 'HTTP ' + code);
if (code >= 400 && code < 500)    return fail('claude_bad_request', 'HTTP ' + code);
if (!(code >= 200 && code < 300)) return fail('claude_unavailable', 'HTTP ' + code);

const body = res.body || {};
if (body.stop_reason === 'refusal')    return fail('claude_refusal', 'model declined');
if (body.stop_reason === 'max_tokens') return fail('claude_truncated', 'hit max_tokens');

let text = '';
for (const blk of (body.content || [])) if (blk.type === 'text') text += blk.text;
// Strip fences / stray prose even though structured outputs should prevent them.
text = text.trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
const s = text.indexOf('{'), e = text.lastIndexOf('}');
if (s !== -1 && e > s) text = text.slice(s, e + 1);

let p;
try { p = JSON.parse(text); } catch (err) { return fail('bad_json', String(err.message)); }

// ---------------------------------------------------------------------------
// SEMANTIC guard on the reply.
//
// Structured outputs guarantee the response matches the SCHEMA. They do not
// guarantee the reply is a sensible sentence. On 2026-09-03 a schema-valid
// response carried reply = ": corrigir - vou responder corretamente.}" and it
// was DELIVERED to a real lead. It parsed cleanly: a non-empty string in a
// string field. Only the content was broken.
//
// Not reproducible in 8 further runs, so this is rare rather than systematic --
// which is exactly why it needs a deterministic check rather than a better
// prompt. Structural markers only; nothing language-specific, since replies are
// pt-PT / en / es.
// ---------------------------------------------------------------------------
// §9.10, deterministically. The prompt says "offer only these times"; on
// 2026-09-04 the model was asked about a day that was NOT in AVAILABLE_SLOTS
// and answered "no sabado dia 12 tenho as 14:00 ou as 15:00" -- two times
// nobody had supplied. The never-invent probe suite scored 18/18 throughout,
// because every case in it asked about a day the list covered.
//
// So this is a check, not a better prompt. A time in the reply must appear in
// the list the workflow supplied; if none was supplied, no time may appear at
// all. A rejection routes into the existing guard-retry, and escalates if the
// retry also fails.
function timesNotSupplied(reply, slots) {
  const supplied = new Set();
  for (const s of (slots || [])) {
    const hhmm = String(s.timeLocal || '');
    const m = hhmm.match(/^(\d{1,2}):(\d{2})$/);
    if (m) supplied.add(String(Number(m[1])) + ':' + m[2]);
  }
  const found = new Set();
  const rx = /\b([01]?\d|2[0-3])[:h]([0-5]\d)\b/g;
  let m2;
  while ((m2 = rx.exec(String(reply || ''))) !== null) {
    found.add(String(Number(m2[1])) + ':' + m2[2]);
  }
  const bad = [...found].filter(t => !supplied.has(t));
  return bad;
}

function replyLooksBroken(s) {
  const t = (s || '').trim();
  if (t.length < 15) return 'too short (' + t.length + ' chars)';
  if (':;,.})]>'.includes(t[0])) return 'starts with punctuation: ' + JSON.stringify(t[0]);
  if (t.includes('{') || t.includes('}')) return 'contains a brace - JSON leaked into the reply';
  if (t.split(/\s+/).filter(Boolean).length < 3) return 'fewer than 3 words';
  if (!/[a-zA-ZÀ-ÿ]/.test(t)) return 'contains no letters';
  return null;
}

const REQUIRED = ['reply','lead_type','stage','intent','wants_booking','needs_human'];
for (const k of REQUIRED) if (!(k in p)) return fail('bad_json', 'missing key: ' + k);
if (typeof p.reply !== 'string' || !p.reply.trim()) return fail('bad_json', 'empty reply');
if (typeof p.needs_human !== 'boolean') return fail('bad_json', 'needs_human not boolean');

const broken = replyLooksBroken(p.reply);
if (broken) return fail('bad_reply', 'reply rejected: ' + broken);

// A booked viewing is restated from what we stored, so its time is legitimate
// even once the offer list has been cleared.
const bookedTime = (b.bookingIntent === 'already_booked' && b.existingBooking)
  ? [b.existingBooking] : [];
const allowed = (b.slots || []).concat(
  (b.bookingSlot ? [b.bookingSlot] : []), bookedTime).map(s => ({
    timeLocal: s.timeLocal || (s.local ? String(s.local).slice(11, 16) : null) }));
const invented = timesNotSupplied(p.reply, allowed);
if (invented.length) {
  return fail('bad_reply', 'reply named times the workflow never supplied: ' + invented.join(', '));
}



// §0, and this is the instance that reached a real prospect. Before the model
// wrote anything, the workflow established whether a property has a name. If it
// does not, the reply may not call the appointment a viewing -- "a sua visita
// esta confirmada" about a property nobody had ever identified.
//
// The prompt says this too. The prompt is not the guard: on 2026-09-05 the same
// prompt already forbade asserting anything the model could not see.
//
// Note the condition is `!== 'viewing'`, not `=== 'meeting'`. If the field is
// ever missing the guard stays ON, which costs a retry; the other way round it
// silently stops running and this defect returns unannounced.
if (b.appointmentKind !== 'viewing') {
  const vc = viewingClaim(p.reply);
  if (vc) {
    return fail('bad_reply',
      'reply called the appointment a viewing when no property has been named: "' + vc + '"');
  }
}

// 2026-09-12: a reply may assert an existing appointment ONLY when the workflow
// holds one or is creating one this turn. Otherwise "ja tem uma reuniao
// marcada" is the model repeating a confirmation the calendar has since lost.
// Second line of defence -- the BOOKING STATUS note in the prompt is the fix;
// this catches the common shapes and fails loudly (retry, then escalate).
const holdsBooking = b.bookingIntent === 'already_booked' && !!b.existingBooking;
const creatingBooking = b.bookingIntent === 'confirm' && !!b.bookingSlot;
if (!holdsBooking && !creatingBooking) {
  const bcm = bookingClaim(p.reply);
  if (bcm) {
    return fail('bad_reply',
      'reply asserted an appointment the workflow does not hold: "' + bcm + '"');
  }
}

// Sanity-check extracted money before it is ever trusted downstream (spec 4.3).
// Bad structured data is worse than absent structured data.
const rejected = [];
const sane = (v) => {
  if (v === null || v === undefined) return null;
  const n = Number(v);
  if (!Number.isFinite(n)) return null;
  if (n < 1000 || n > 50000000) { rejected.push(n); return null; }
  return n;
};
p.budget_min = sane(p.budget_min);
p.budget_max = sane(p.budget_max);
if (p.budget_min !== null && p.budget_max !== null && p.budget_min > p.budget_max) {
  rejected.push(p.budget_min, p.budget_max);
  p.budget_min = null; p.budget_max = null;
}

return [{ json: { ...b, ok: true, errorType: null, errorMessage: null, durationMs,
                  usage: body.usage || null, modelUsed: body.model || null,
                  rejectedBudgets: rejected, parsed: p } }];

const p   = $('AfterBooking').first().json;
const res = $input.first().json;
const ok  = res.statusCode >= 200 && res.statusCode < 300;
const b   = res.body || {};
return [{ json: { ...p,
  sendOk: ok,
  twilioSid: ok ? (b.sid || null) : null,
  twilioErrorCode: ok ? null : (b.code || res.statusCode),
  twilioErrorMessage: ok ? null : String(b.message || '').slice(0, 300),
} }];

// Read AfterSend explicitly. This node sits after StoreOutbound, whose output is
// an HTTP response ({statusCode, body}) - NOT the accumulated item. Using
// $input here silently produced client_automation_id: undefined, and the run
// insert failed a NOT NULL constraint invisibly because neverError swallows 4xx.
const j = $('AfterSend').first().json;
const store = $('StoreOutbound').first().json;
const lu = $('AfterLeadUpdate').first().json;
const sl = $('ProposeSlots').first().json;
const bk = $('AfterBooking').first().json;
// A swallowed 4xx here is how the viewing.booked event went missing once.
let vbStatus = null; try { vbStatus = $('EventViewingBooked').first().json.statusCode; } catch (e) { vbStatus = null; }
let rbk = {}; try { rbk = $('ResolveBooking').first().json || {}; } catch (e) { rbk = {}; }
let bcStatus = null; try { bcStatus = $('EventBookingCheck').first().json.statusCode; } catch (e) { bcStatus = null; }
const u = j.usage || {};
return [{ json: { run: {
  client_automation_id: j.clientAutomationId,
  status: j.sendOk ? 'success' : 'error',
  started_at: j.startedAt,
  finished_at: new Date().toISOString(),
  duration_ms: Math.max(0, new Date() - new Date(j.startedAt)),
  error_type: j.sendOk ? null : 'whatsapp_send_failed',
  error_message: j.sendOk ? null : ('twilio ' + j.twilioErrorCode + ': ' + j.twilioErrorMessage),
  payload: { checkpoint: 'B1', model: j.modelUsed, claude_ms: j.durationMs,
             input_tokens: u.input_tokens ?? null, output_tokens: u.output_tokens ?? null,
             history_messages: j.historyCount, current_turn_from_history: j.currentTurnAlreadyPresent,
             needs_human: j.parsed ? j.parsed.needs_human : null,
             intent: j.parsed ? j.parsed.intent : null,
             rejected_budgets: (j.rejectedBudgets || []).length,
             twilio_sid: j.twilioSid, first_contact: j.isNewLead,
             outbound_row_status: store.statusCode,
             // B2: what the merge actually did, so an erased field would be visible
             lead_update_ok: lu.leadUpdateOk, lead_update_status: lu.leadUpdateStatus,
             stage_before: lu.stageBefore, stage_after: lu.stageAfter,
             became_qualified: lu.becameQualified,
             fields_changed: (lu.changed || []).length,
             fields_protected: (lu.kept || []).length,
             slots_offered: (sl.slotLines || []).length, slot_error: sl.slotError,
             prefer_date: sl.preferDate, prefer_status: sl.preferStatus,
             prefer_requested: sl.preferRequested, offer_source: sl.offerSource,
             busy_intervals: sl.busyIntervals, freebusy_status: sl.freeBusyStatus,
             wants_booking: lu.parsed ? lu.parsed.wants_booking : null,
             booking_intent: bk.bookingIntent, booking_result: bk.bookingResult,
             booking_error: bk.bookingError, event_id: bk.bookedEventId,
             matched_by: bk.bookingMatchedBy, conflict: bk.conflict || null, promised_but_failed: bk.promisedButFailed, reply_guard: lu.errorMessage || null, viewing_event_status: vbStatus,
             booking_check: rbk.bookingCheck || 'none', booking_check_status: rbk.bookingCheckStatus == null ? null : rbk.bookingCheckStatus,
             booking_check_error: rbk.bookingCheckError || null, booking_check_event_status: bcStatus },
} } }];

const a = $('AfterLead').first().json;
return [{ json: { run: {
  client_automation_id: a.clientAutomationId,
  status: 'success',
  started_at: a.startedAt,
  finished_at: new Date().toISOString(),
  duration_ms: Math.max(0, new Date() - new Date(a.startedAt)),
  error_type: null, error_message: null,
  payload: { checkpoint: 'B1', duplicate_delivery: true, sent_to_lead: false },
} } }];

// ============================================================================
// The no-backwards rule is the whole of Gate B2.
//
// B3 moved this chain to run BEFORE the escalation branch. Reason: an escalated
// lead was being handed to a human with a blank row -- the escalation reason
// knew the budget was 3,000,000 while leads.budget_max was still null, because
// escalation bypassed persistence entirely. Extraction is valid whether or not
// the AI is the one who replies next.
//
// Claude returns null for budget when the message is about parking. Writing
// that null straight through erases what was learned three messages ago -- and
// the reply still looks perfect, so it fails INVISIBLY. Nothing downstream can
// tell an erased field from one that was never learned.
//
// So: a populated field NEVER goes back to null, and never goes back to a less
// specific value. Every field below is merged, not assigned.
// ============================================================================
const a   = $('AfterLead').first().json;
const pc  = $('AfterBooking').first().json;
const p   = pc.parsed || {};
const res = $input.first().json;

const httpOk = res.statusCode >= 200 && res.statusCode < 300;
const rows = Array.isArray(res.body) ? res.body : [];
const cur = rows[0] || null;
if (!httpOk || !cur) {
  // Do not guess at a merge against unknown current state -- that is exactly
  // how a field gets silently erased.
  return [{ json: { ...pc, leadUpdateSkipped: true,
                    leadUpdateError: 'could not read current lead (HTTP ' + res.statusCode + ')',
                    patch: null, becameQualified: false, changed: [], kept: [] } }];
}

const changed = [];   // field -> what it became
const kept    = [];   // field -> what was protected from being overwritten
const patch   = {};

// --- scalar fields: fill or improve, never blank -----------------------------
function mergeScalar(field, incoming, opts) {
  opts = opts || {};
  const before = cur[field];
  const isBlank = (v) => v === null || v === undefined ||
                         (typeof v === 'string' && v.trim() === '') ||
                         (opts.blankValues || []).includes(v);
  if (isBlank(incoming)) {
    if (!isBlank(before)) kept.push(field + '=' + before + ' (incoming was null)');
    return;
  }
  if (String(before) === String(incoming)) return;          // no change
  if (!isBlank(before) && opts.onlyIfBlank) {
    kept.push(field + '=' + before + ' (already set)');
    return;
  }
  patch[field] = incoming;
  changed.push(field + ': ' + (before === null ? 'null' : before) + ' -> ' + incoming);
}

// full_name: ProfileName seeded it at Checkpoint A. Let Claude improve on the
// seed once, then stop churning it.
const seededName = a.profileName || null;
mergeScalar('full_name', p.full_name,
            { onlyIfBlank: cur.full_name !== null && cur.full_name !== seededName });

mergeScalar('lead_type', p.lead_type, { blankValues: ['unknown'] });
mergeScalar('timeline',  p.timeline);
mergeScalar('area',      p.area);

// --- budget: sanity-checked in ParseClaude, merged here ----------------------
// ParseClaude already nulled implausible values and collected them. Widening is
// allowed (a lead who says "up to 1.5M" after "up to 800k" has genuinely moved);
// blanking is not.
mergeScalar('budget_min', p.budget_min);
mergeScalar('budget_max', p.budget_max);

// --- qualification jsonb: merge keys, never replace the object ---------------
const q = Object.assign({}, cur.qualification || {});
const notes = p.qualification_notes || {};
for (const k of ['financing', 'bedrooms', 'purpose']) {
  const v = notes[k];
  if (v === null || v === undefined || (typeof v === 'string' && !v.trim())) {
    if (q[k] !== undefined && q[k] !== null) kept.push('qualification.' + k + ' (incoming null)');
    continue;
  }
  if (String(q[k]) !== String(v)) {
    q[k] = v;
    changed.push('qualification.' + k + ': ' + (q[k] === undefined ? 'unset' : q[k]));
  }
}

// Rejected budgets go HERE, not into the numeric columns. Bad structured data is
// worse than absent structured data, because everything downstream trusts it.
const rejected = pc.rejectedBudgets || [];
if (rejected.length) {
  q.rejected_budgets = (q.rejected_budgets || []).concat(
    rejected.map(v => ({ value: v, at: new Date().toISOString(),
                         reason: 'implausible for EUR property budget' })));
  changed.push('qualification.rejected_budgets += ' + rejected.length);
}

// --- store what was actually offered, so C2 can match a confirmation ---------
// Without this, "yes, the Thursday one please" is unresolvable.
const offered = pc.slots || [];
const priorOffer = (cur.qualification || {}).proposed_slots;
const offerChanged = !priorOffer ||
  JSON.stringify((priorOffer.slots || []).map(s => s.startUtc)) !==
  JSON.stringify(offered.map(s => s.startUtc));
if (offered.length && pc.parsed && pc.parsed.wants_booking === true && offerChanged) {
  q.proposed_slots = { at: new Date().toISOString(),
                       prefer_date: pc.preferDate || null,
                       prefer_requested: pc.preferRequested || null,
                       prefer_status: pc.preferStatus || 'none',
                       slots: offered.map(s => ({ startUtc: s.startUtc, endUtc: s.endUtc,
                                                  local: s.startLocal, zone: s.zone })) };
  changed.push('qualification.proposed_slots = ' + offered.length + ' slot(s)');
}

// --- stage: monotonic along new -> contacted -> qualified --------------------
// viewing_booked must outrank qualified, or the no-backwards rule silently
// blocks every booking -- it was absent from this map until C2.
const RANK = { new: 0, nurturing: 1, contacted: 1, qualified: 2, viewing_booked: 3 };
const before = cur.stage || 'new';
let proposed = p.stage || null;

// Checkpoint C2 lifts the B-era block, but ONLY the workflow may set this
// stage. The model asking for viewing_booked is still refused -- an event
// either exists in Google or it does not, and the model does not know.
const bk = $('AfterBooking').first().json;
if (proposed === 'viewing_booked' && !bk.booked) {
  q.stage_signals = (q.stage_signals || []).concat(
    [{ rejected: 'viewing_booked', reason: 'no event was created', at: new Date().toISOString() }]);
  changed.push('qualification.stage_signals += rejected viewing_booked');
  proposed = null;
}
if (bk.booked && bk.bookingResult === 'created' && bk.bookingSlot) {
  proposed = 'viewing_booked';
  q.booking = { event_id: bk.bookedEventId, startUtc: bk.bookingSlot.startUtc,
                endUtc: bk.bookingSlot.endUtc, local: bk.bookingSlot.local,
                zone: bk.bookingSlot.zone, matched_by: bk.bookingMatchedBy,
                at: new Date().toISOString() };
  // The offer has been taken up; leaving it in place would let a later message
  // match a slot that is now the booking itself.
  delete q.proposed_slots;
  changed.push('qualification.booking = ' + bk.bookedEventId);
}

// A booking retired this turn -- its slot has passed, or the event is no longer
// in the calendar -- is ARCHIVED, not deleted: the trail stays on the lead.
// Stage is deliberately not touched here (see 1.4 in the 2026-09-11 brief).
const rb = $('ResolveBooking').first().json;
if (rb.bookingRetired && q.booking && q.booking.event_id === rb.bookingRetired.event_id) {
  q.past_bookings = (q.past_bookings || []).concat([rb.bookingRetired]);
  delete q.booking;
  changed.push('qualification.booking retired: ' + rb.bookingRetired.retired_reason);
}

let stage = before;
if (proposed && proposed !== before) {
  if (proposed === 'nurturing') {
    // A qualified lead is not demoted to nurturing on one quiet message; record
    // the signal instead so it is not lost.
    if (RANK[before] >= RANK.qualified) {
      q.stage_signals = (q.stage_signals || []).concat(
        [{ signal: 'nurturing', suppressed_from: before, at: new Date().toISOString() }]);
      kept.push('stage=' + before + ' (nurturing signal recorded, not applied)');
    } else {
      stage = 'nurturing';
    }
  } else if ((RANK[proposed] ?? 0) > (RANK[before] ?? 0)) {
    stage = proposed;
  } else {
    kept.push('stage=' + before + ' (model proposed ' + proposed + ', a regression)');
  }
}
if (stage !== before) { patch.stage = stage; changed.push('stage: ' + before + ' -> ' + stage); }

if (JSON.stringify(q) !== JSON.stringify(cur.qualification || {})) patch.qualification = q;

// --- always touched ---------------------------------------------------------
const now = new Date().toISOString();
patch.last_contact_at = now;
patch.updated_at = now;

// lead.qualified fires ONCE, on the transition -- not on every later message.
const becameQualified = (before !== 'qualified' && stage === 'qualified');

return [{ json: { ...pc, leadUpdateSkipped: false, leadUpdateError: null,
                  patch, becameQualified, changed, kept,
                  stageBefore: before, stageAfter: stage } }];

// Lesson 9: this node follows an HTTP call, so $input is a response envelope
// ({statusCode, headers, body}), NOT the accumulated item. Read the upstream
// node explicitly. Reading $input here is what silently produced
// client_automation_id: undefined at B1.
const m   = $('MergeLeadFields').first().json;
const res = $input.first().json;
const ok  = res.statusCode >= 200 && res.statusCode < 300;
const rows = Array.isArray(res.body) ? res.body : [];
return [{ json: { ...m,
  leadUpdateOk: ok && !m.leadUpdateSkipped,
  leadUpdateStatus: res.statusCode,
  leadAfter: rows[0] || null,
} }];

// The inbound message was already stored by Checkpoint A. A human owns this
// lead now, so we deliberately do not reply. Silence here is correct -- the
// lead already received the handoff note when the escalation happened.
const a = $('AfterLead').first().json;
return [{ json: { run: {
  client_automation_id: a.clientAutomationId,
  status: 'success',
  started_at: a.startedAt,
  finished_at: new Date().toISOString(),
  duration_ms: Math.max(0, new Date() - new Date(a.startedAt)),
  error_type: null, error_message: null,
  payload: { checkpoint: 'B3', silenced_escalated_lead: true,
             escalated_at: a.escalatedAt, sent_to_lead: false, ai_called: false },
} } }];

// ============================================================================
// Is there a property to view, or only a lead to meet? — shared source.
//
// Embedded verbatim into BuildClaudeRequest (which decides) and into
// ParseClaude / ParseGuardRetry (which check the reply). Unit-tested standalone
// in tests/appointment_kind.test.js, which loads THIS file rather than a copy.
//
// WHY THIS EXISTS
// On 2026-09-05 the Concierge sent a real lead:
//     "A sua visita esta confirmada para sexta-feira, dia 11 de setembro,
//      as 10:00, hora de Lisboa."
// The calendar half was correct: the slot was genuinely free, the event was
// created, the agent was notified. The CLAIM was not. Nobody -- not the lead,
// not an agent, not the Concierge -- had ever named a property. It booked a
// viewing of nothing, and the lead would have found out on the doorstep.
//
// engineering-lessons.md §0: never let a generated message narrate a future you
// have not secured. A property nobody has named is a future nobody has secured.
//
// THE RULE
// Unless a specific property has been named in the conversation, the
// appointment is a FIRST MEETING with an agent, and must be described as one.
// That is normal in this market and, unlike "visita", it is true. "visita" /
// "viewing" is reserved for when a property has a name.
//
// THE BIAS IS ONE-DIRECTIONAL, and deliberately so -- the same rule that
// governs matchConfirmation(). When in doubt it is a MEETING:
//   - calling a real viewing a meeting UNDER-describes an appointment that is
//     going to happen anyway. A human corrects it in one message.
//   - calling a meeting a viewing INVENTS a property. Nothing downstream can
//     correct that, because the lead has already been told.
// Every unknown below therefore resolves to 'meeting'.
//
// WHY NOT ASK THE MODEL
// Same reason the workflow picks the slots and the model only phrases them: the
// appointment kind decides what goes in a real agent's calendar and what a
// prospect is told. It has to be answerable from stored data. Asking the model
// "was a property discussed?" would make the guard depend on the judgement it
// exists to not trust.
// ============================================================================

// ---------------------------------------------------------------------------
// A listing reference is the only thing that counts as "a property has a name".
//
// An address or a house name ("a moradia na Rua das Flores") would need
// judgement to recognise, and judgement here means a model. So they are NOT
// detected, and such a conversation books a meeting. That is the safe
// direction and it is an honest under-description, not a wrong one.
//
// Two forms:
//   bare      A-1042, LX-2001            uppercase block, dash, 3-5 digits
//   keyword   Ref B-2001, referencia 10234, reference: LX88
// The bare form is case-SENSITIVE on purpose. Lowercase "t-3000" in prose is
// far more likely to be noise than a reference; a real one is written in caps
// or introduced by the word "ref".
// ---------------------------------------------------------------------------
const REF_BARE = /\b[A-Z]{1,3}-\d{3,5}\b/g;
const REF_KEYWORD =
  /\b(?:ref|refa|referencia|reference)\b\.?\s*[:#-]?\s*([A-Za-z]{0,4}-?\d{2,6}[A-Za-z]?)\b/gi;

function deaccent(s) {
  return String(s == null ? '' : s).normalize('NFD').replace(/[̀-ͯ]/g, '');
}

// findPropertyRefs(text) -> array of normalised reference strings (may be empty)
function findPropertyRefs(text) {
  const raw = String(text == null ? '' : text);
  if (!raw.trim()) return [];
  const found = [];
  const add = (v) => {
    const s = String(v).toUpperCase().replace(/\s+/g, '');
    if (s && found.indexOf(s) === -1) found.push(s);
  };

  // Bare form reads the ORIGINAL text: case is part of the signal.
  let m;
  REF_BARE.lastIndex = 0;
  while ((m = REF_BARE.exec(raw)) !== null) add(m[0]);

  // Keyword form reads the de-accented text so "referencia" and "referência"
  // are the same word.
  const flat = deaccent(raw);
  REF_KEYWORD.lastIndex = 0;
  while ((m = REF_KEYWORD.exec(flat)) !== null) add(m[1]);

  return found;
}

// ---------------------------------------------------------------------------
// appointmentKindFor(rows) -> {kind: 'viewing'|'meeting', refs: [...]}
//
// `rows` are message rows: {direction, body, ai_generated}.
//
// THE CONCIERGE'S OWN WORDS ARE NOT EVIDENCE. It has no inventory, so any
// reference it produced would be one it invented -- and trusting it would
// re-open exactly this defect one layer down. Outbound rows count only when
// they are explicitly marked as NOT ai_generated, which is a human agent
// replying from the cockpit (or a fixed config string, which never carries a
// reference). An outbound row whose origin cannot be established is ignored:
// if `ai_generated` is missing from the query, every conversation books a
// meeting, which is the fail-SAFE direction rather than the fail-open one.
// ---------------------------------------------------------------------------
function appointmentKindFor(rows) {
  const refs = [];
  for (const r of (Array.isArray(rows) ? rows : [])) {
    if (!r) continue;
    if (r.direction === 'outbound' && r.ai_generated !== false) continue;
    for (const ref of findPropertyRefs(r.body)) {
      if (refs.indexOf(ref) === -1) refs.push(ref);
    }
  }
  return { kind: refs.length ? 'viewing' : 'meeting', refs };
}

// ---------------------------------------------------------------------------
// viewingClaim(reply) -> the offending phrase, or null.
//
// The prompt tells the model which kind of appointment this is. This is the
// CHECK, not a better prompt -- §11 instance 11: when wording cannot hold a
// line reliably, replace it with something that fails loudly. The model wrote
// "a sua visita esta confirmada" under a prompt that already forbade asserting
// things it could not see.
//
// Applied only when the kind is 'meeting'. A rejection routes into the existing
// guard-retry; if the retry also claims a viewing, the turn escalates and NO
// booking is created -- a human holds a lead who is ready to book, which is a
// recoverable outcome, unlike the message this guard prevents.
//
// The list is not exhaustive and is not meant to be. It covers the words that
// NAME the appointment in the three languages the Concierge speaks. Paraphrases
// it misses are caught, if at all, by the prompt -- this is the backstop, and a
// backstop that tried to be complete would start rejecting honest sentences.
// ---------------------------------------------------------------------------
const VIEWING_WORDS = [
  // pt/es visita, visitas, visitar, visita-la; en visit, visits, visiting
  { rx: /\bvisit\w*/, label: 'visit*' },
  { rx: /\bviewings?\b/, label: 'viewing' },
  { rx: /\bview the\b/, label: 'view the' },
  { rx: /\bver (?:o|a|os|as|el|la|los|las) (?:imovel|imoveis|casa|moradia|apartamento|andar|vivienda|piso|propriedade|propiedad)\b/,
    label: 'ver o imovel' },
  { rx: /\bsee the (?:property|house|apartment|flat|villa)\b/, label: 'see the property' },
];

function viewingClaim(reply) {
  const t = deaccent(reply).toLowerCase();
  if (!t.trim()) return null;
  for (const w of VIEWING_WORDS) {
    const m = t.match(w.rx);
    if (m) return m[0];
  }
  return null;
}


// ============================================================================
// Does the reply assert an appointment the workflow does not hold? — shared
// source. Embedded verbatim into ParseClaude and ParseGuardRetry. Unit-tested
// standalone in tests/booking_claim.test.js, which loads THIS file.
//
// WHY THIS EXISTS
// On 2026-09-12 a lead whose booking had been retired asked for a meeting and
// was told "Ja tem uma reuniao marcada para terca-feira, dia 15 ... as 09:00".
// The workflow held no booking. The model read its own confirmation twenty
// lines up the transcript and repeated it. The time was on the offered list,
// so the invented-time guard passed; "reuniao" is not "visita", so the
// viewing-claim guard passed. Nothing checked the claim itself.
//
// SECOND LINE OF DEFENCE, NOT THE FIRST
// The prompt now states the absence of a booking every turn, with the retired
// one named. That is the fix. Phrase matching across three languages will miss
// paraphrases -- "a reuniao fica entao para terca" is an assertion that no
// short list anticipates completely -- so this guard exists to fail loudly on
// the common shapes, never to justify a weaker prompt. Same posture as
// viewingClaim: a backstop that tried to be complete would start rejecting
// honest sentences.
//
// SHAPE
// Statements only: a sentence ending in "?" is an offer or a question, never
// an assertion, so it is skipped. Negations ("ja nao esta marcada", "is no
// longer in the diary") do not match by construction -- every pattern needs
// the affirmative form. Applied ONLY when the workflow holds no booking and is
// not creating one this turn; an honest confirmation is never tested.
// ============================================================================

function deaccentClaim(s) {
  return String(s == null ? '' : s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
}

const BOOKING_CLAIMS = [
  // --- pt ------------------------------------------------------------------
  // "ja tem uma reuniao marcada", "ja esta confirmada", "ja fica agendada"
  { rx: /\bja (?:tem|temos|esta|fica|ficou) [^.!?\n]{0,40}?(?:marcad|confirmad|agendad|reuniao|visita)/, label: 'ja tem ... marcada' },
  // "a reuniao fica entao para terca", "a sua visita esta marcada", "a reuniao continua para"
  { rx: /\b(?:reuniao|visita|marcacao|conversa|encontro) (?:fica|esta|ficou|continua|mantem-se) (?:entao |assim |portanto |sempre )?(?:marcad|confirmad|agendad|para\b|na\b|no\b|as\b)/, label: 'a reuniao fica para' },
  // "esta marcada para terca-feira", "ficou confirmada para dia 15"
  { rx: /\b(?:esta|ficou|fica|estao|ficam) (?:entao |assim )?(?:marcad[ao]s?|confirmad[ao]s?|agendad[ao]s?) para (?:o |a |as |os |o dia |dia |segunda|terca|quarta|quinta|sexta|sabado|domingo|\d)/, label: 'esta marcada para <dia>' },
  // "temos a reuniao marcada", "mantemos a visita marcada"
  { rx: /\b(?:temos|mantemos) (?:a |uma |essa |esta )?(?:reuniao|visita|marcacao|conversa) (?:marcad|confirmad|agendad)/, label: 'temos a reuniao marcada' },
  // --- es ------------------------------------------------------------------
  { rx: /\bya (?:tiene|tenemos|esta|queda) [^.!?\n]{0,40}?(?:cita|reunion|visita|confirmad|agendad|reservad|programad)/, label: 'ya tiene ... cita' },
  { rx: /\b(?:cita|reunion|visita) (?:queda|esta|sigue|se mantiene) (?:entonces )?(?:confirmad|agendad|reservad|programad|para\b|el\b|la\b|los\b|las\b)/, label: 'la cita queda para' },
  { rx: /\b(?:esta|queda|quedo|quedan) (?:entonces )?(?:confirmad[ao]s?|agendad[ao]s?|reservad[ao]s?|programad[ao]s?) para (?:el |la |las |los |lunes|martes|miercoles|jueves|viernes|sabado|domingo|\d)/, label: 'queda confirmada para <dia>' },
  // --- en ------------------------------------------------------------------
  { rx: /\byou(?:'re| are)? already (?:have|booked|down|set|confirmed)\b/, label: 'you already have' },
  { rx: /\b(?:your|the) (?:meeting|viewing|appointment|call) (?:is|remains|stays|is still) (?:set |booked |confirmed |scheduled |in the diary |on )?(?:for|on|at)\b/, label: 'your meeting is for' },
  { rx: /\b(?:is|are|remains|stays) (?:already |still |now )?(?:booked|confirmed|scheduled|in the diary) for (?:the |mon|tue|wed|thu|fri|sat|sun|\d|next|this|tomorrow)/, label: 'is booked for <day>' },
  { rx: /\bwe have you (?:booked|down) for\b/, label: 'we have you booked for' },
  { rx: /\bi(?:'ve| have) (?:got )?you (?:booked|down) for\b/, label: 'I have you booked for' },
];

// bookingClaim(reply) -> the offending phrase (label), or null.
function bookingClaim(reply) {
  const raw = String(reply == null ? '' : reply);
  if (!raw.trim()) return null;
  // Sentence by sentence, so a question is never read as an assertion.
  const sentences = raw.split(/(?<=[.!?\n])\s+|\n+/);
  for (const sentence of sentences) {
    const s = sentence.trim();
    if (!s || s.endsWith('?')) continue;
    const t = deaccentClaim(s);
    for (const c of BOOKING_CLAIMS) {
      const m = t.match(c.rx);
      if (m) return m[0];
    }
  }
  return null;
}



// Defensive parse. Structured outputs (output_config.format) already constrain the
// response to the schema at the API level, so this is a BACKSTOP, not the primary
// mechanism - but it is not dead code: structured outputs do NOT hold when
// stop_reason is 'refusal' or 'max_tokens'.
const b   = $('BuildClaudeRequest').first().json;
const res = $input.first().json;
const started = b.claudeStartedAt;
const finished = new Date().toISOString();
const durationMs = Math.max(0, new Date(finished) - new Date(started));

function fail(errorType, errorMessage) {
  return [{ json: { ...b, wasGuardRetry: true, ok: false, errorType, errorMessage, durationMs,
                    usage: null, parsed: null } }];
}

const code = res.statusCode;
if (code === 401 || code === 403) return fail('claude_auth', 'HTTP ' + code);
if (code >= 400 && code < 500)    return fail('claude_bad_request', 'HTTP ' + code);
if (!(code >= 200 && code < 300)) return fail('claude_unavailable', 'HTTP ' + code);

const body = res.body || {};
if (body.stop_reason === 'refusal')    return fail('claude_refusal', 'model declined');
if (body.stop_reason === 'max_tokens') return fail('claude_truncated', 'hit max_tokens');

let text = '';
for (const blk of (body.content || [])) if (blk.type === 'text') text += blk.text;
// Strip fences / stray prose even though structured outputs should prevent them.
text = text.trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
const s = text.indexOf('{'), e = text.lastIndexOf('}');
if (s !== -1 && e > s) text = text.slice(s, e + 1);

let p;
try { p = JSON.parse(text); } catch (err) { return fail('bad_json', String(err.message)); }

// ---------------------------------------------------------------------------
// SEMANTIC guard on the reply.
//
// Structured outputs guarantee the response matches the SCHEMA. They do not
// guarantee the reply is a sensible sentence. On 2026-09-03 a schema-valid
// response carried reply = ": corrigir - vou responder corretamente.}" and it
// was DELIVERED to a real lead. It parsed cleanly: a non-empty string in a
// string field. Only the content was broken.
//
// Not reproducible in 8 further runs, so this is rare rather than systematic --
// which is exactly why it needs a deterministic check rather than a better
// prompt. Structural markers only; nothing language-specific, since replies are
// pt-PT / en / es.
// ---------------------------------------------------------------------------
// §9.10, deterministically. The prompt says "offer only these times"; on
// 2026-09-04 the model was asked about a day that was NOT in AVAILABLE_SLOTS
// and answered "no sabado dia 12 tenho as 14:00 ou as 15:00" -- two times
// nobody had supplied. The never-invent probe suite scored 18/18 throughout,
// because every case in it asked about a day the list covered.
//
// So this is a check, not a better prompt. A time in the reply must appear in
// the list the workflow supplied; if none was supplied, no time may appear at
// all. A rejection routes into the existing guard-retry, and escalates if the
// retry also fails.
function timesNotSupplied(reply, slots) {
  const supplied = new Set();
  for (const s of (slots || [])) {
    const hhmm = String(s.timeLocal || '');
    const m = hhmm.match(/^(\d{1,2}):(\d{2})$/);
    if (m) supplied.add(String(Number(m[1])) + ':' + m[2]);
  }
  const found = new Set();
  const rx = /\b([01]?\d|2[0-3])[:h]([0-5]\d)\b/g;
  let m2;
  while ((m2 = rx.exec(String(reply || ''))) !== null) {
    found.add(String(Number(m2[1])) + ':' + m2[2]);
  }
  const bad = [...found].filter(t => !supplied.has(t));
  return bad;
}

function replyLooksBroken(s) {
  const t = (s || '').trim();
  if (t.length < 15) return 'too short (' + t.length + ' chars)';
  if (':;,.})]>'.includes(t[0])) return 'starts with punctuation: ' + JSON.stringify(t[0]);
  if (t.includes('{') || t.includes('}')) return 'contains a brace - JSON leaked into the reply';
  if (t.split(/\s+/).filter(Boolean).length < 3) return 'fewer than 3 words';
  if (!/[a-zA-ZÀ-ÿ]/.test(t)) return 'contains no letters';
  return null;
}

const REQUIRED = ['reply','lead_type','stage','intent','wants_booking','needs_human'];
for (const k of REQUIRED) if (!(k in p)) return fail('bad_json', 'missing key: ' + k);
if (typeof p.reply !== 'string' || !p.reply.trim()) return fail('bad_json', 'empty reply');
if (typeof p.needs_human !== 'boolean') return fail('bad_json', 'needs_human not boolean');

const broken = replyLooksBroken(p.reply);
if (broken) return fail('bad_reply', 'reply rejected: ' + broken);

// A booked viewing is restated from what we stored, so its time is legitimate
// even once the offer list has been cleared.
const bookedTime = (b.bookingIntent === 'already_booked' && b.existingBooking)
  ? [b.existingBooking] : [];
const allowed = (b.slots || []).concat(
  (b.bookingSlot ? [b.bookingSlot] : []), bookedTime).map(s => ({
    timeLocal: s.timeLocal || (s.local ? String(s.local).slice(11, 16) : null) }));
const invented = timesNotSupplied(p.reply, allowed);
if (invented.length) {
  return fail('bad_reply', 'reply named times the workflow never supplied: ' + invented.join(', '));
}



// §0, and this is the instance that reached a real prospect. Before the model
// wrote anything, the workflow established whether a property has a name. If it
// does not, the reply may not call the appointment a viewing -- "a sua visita
// esta confirmada" about a property nobody had ever identified.
//
// The prompt says this too. The prompt is not the guard: on 2026-09-05 the same
// prompt already forbade asserting anything the model could not see.
//
// Note the condition is `!== 'viewing'`, not `=== 'meeting'`. If the field is
// ever missing the guard stays ON, which costs a retry; the other way round it
// silently stops running and this defect returns unannounced.
if (b.appointmentKind !== 'viewing') {
  const vc = viewingClaim(p.reply);
  if (vc) {
    return fail('bad_reply',
      'reply called the appointment a viewing when no property has been named: "' + vc + '"');
  }
}

// 2026-09-12: a reply may assert an existing appointment ONLY when the workflow
// holds one or is creating one this turn. Otherwise "ja tem uma reuniao
// marcada" is the model repeating a confirmation the calendar has since lost.
// Second line of defence -- the BOOKING STATUS note in the prompt is the fix;
// this catches the common shapes and fails loudly (retry, then escalate).
const holdsBooking = b.bookingIntent === 'already_booked' && !!b.existingBooking;
const creatingBooking = b.bookingIntent === 'confirm' && !!b.bookingSlot;
if (!holdsBooking && !creatingBooking) {
  const bcm = bookingClaim(p.reply);
  if (bcm) {
    return fail('bad_reply',
      'reply asserted an appointment the workflow does not hold: "' + bcm + '"');
  }
}

// Sanity-check extracted money before it is ever trusted downstream (spec 4.3).
// Bad structured data is worse than absent structured data.
const rejected = [];
const sane = (v) => {
  if (v === null || v === undefined) return null;
  const n = Number(v);
  if (!Number.isFinite(n)) return null;
  if (n < 1000 || n > 50000000) { rejected.push(n); return null; }
  return n;
};
p.budget_min = sane(p.budget_min);
p.budget_max = sane(p.budget_max);
if (p.budget_min !== null && p.budget_max !== null && p.budget_min > p.budget_max) {
  rejected.push(p.budget_min, p.budget_max);
  p.budget_min = null; p.budget_max = null;
}

return [{ json: { ...b, wasGuardRetry: true, ok: true, errorType: null, errorMessage: null, durationMs,
                  usage: body.usage || null, modelUsed: body.model || null,
                  rejectedBudgets: rejected, parsed: p } }];

// ============================================================================
// Deterministic language detection for SYSTEM messages — Checkpoint D2.
//
// WHY THIS IS NOT A MODEL CALL
// The handoff note is the message sent when the Concierge cannot answer: the
// model refused, returned unparseable JSON twice, or produced a reply that had
// to be discarded. It is the one message that must still work *when the model
// has failed*, which rules out asking a model — either to write it or to say
// what language to write it in.
//
// So: fixed strings from config, keyed by language, chosen by the rules below.
//
// This is a classifier for THREE known languages on SHORT messages, not a
// general-purpose one. It is allowed to be unsure, and being unsure is safe:
// an undecided result falls back to the client's configured default rather
// than guessing. Sending Portuguese to a Portuguese lead is the win; sending
// Spanish to a Portuguese lead because two words matched is worse than the
// English we send today.
// ============================================================================

// Accented and punctuation marks that occur in ONE of the three languages and
// effectively settle it on their own. Checked before normalisation, because
// stripping diacritics destroys exactly the signal that discriminates pt from
// es -- the two languages that actually get confused.
const HARD_MARKERS = [
  { lang: 'pt', rx: /[ãõ]/, weight: 6 },          // não, mão, então, opções
  { lang: 'pt', rx: /ç/, weight: 5 },             // preço, começar
  { lang: 'es', rx: /ñ/, weight: 6 },             // mañana, año, señor
  { lang: 'es', rx: /[¿¡]/, weight: 6 },          // inverted punctuation
];

// Function words and greetings. Deliberately excludes anything the three share
// (que, para, no, si/sim, por favor, esta) -- a shared word is not evidence.
// Function words. Only DISCRIMINATING tokens: anything the languages share
// (que, para, no, casa, como, por favor) is not evidence and is excluded.
// The pt/es minimal pairs do most of the work here -- com/con, uma/una,
// quando/cuando, muito/mucho -- because those two are the pair that actually
// gets confused.
const WORD_MARKERS = {
  pt: ['nao', 'obrigado', 'obrigada', 'ola', 'voce', 'gostaria', 'queria',
       'muito', 'estou', 'tenho', 'tem', 'quero', 'bom dia', 'boa tarde',
       'boa noite', 'feira', 'imovel', 'imoveis', 'moradia', 'preciso',
       'gostava', 'entao', 'onde', 'com', 'uma', 'um', 'quando', 'quanto',
       'qual', 'mais', 'na', 'nas', 'dos', 'das', 'ate', 'posso', 'pode',
       'procuro', 'visitar', 'marcar', 'falar', 'pessoa', 'afinal', 'mudar'],
  es: ['hola', 'gracias', 'quisiera', 'usted', 'tambien', 'buenos dias',
       'buenas tardes', 'buenas noches', 'vivienda', 'piso', 'necesito',
       'busco', 'con', 'una', 'cuando', 'cuanto', 'donde', 'ahora', 'manana',
       'el', 'los', 'las', 'muy', 'mucho', 'estoy', 'tengo', 'puedo',
       'hablar', 'jueves', 'viernes', 'quiero'],
  en: ['the', 'and', 'you', 'are', 'is', 'would', 'like', 'hello', 'hi',
       'thanks', 'thank', 'please', 'can', 'i', 'im', 'looking', 'house',
       'flat', 'apartment', 'available', 'viewing', 'week', 'time', 'do',
       'have', 'see', 'come', 'speak', 'person', 'anything', 'something'],
};

const SUPPORTED = ['pt', 'en', 'es'];

// detectLanguage(text) -> {lang: 'pt'|'en'|'es'|null, scores, confident}
// Returns null when the evidence is thin or the top two are close. Callers
// must treat null as "use the configured default", never as a language.
function detectLanguage(text) {
  const raw = String(text || '');
  const out = (lang, scores, confident) => ({ lang, scores, confident });
  if (!raw.trim()) return out(null, { pt: 0, en: 0, es: 0 }, false);

  const lower = raw.toLowerCase();
  const scores = { pt: 0, en: 0, es: 0 };

  for (const m of HARD_MARKERS) {
    if (m.rx.test(lower)) scores[m.lang] += m.weight;
  }

  // Normalise for word matching so "voce"/"você" and "manana"/"mañana" both
  // land, having already banked the diacritic evidence above.
  const flat = ' ' + lower.normalize('NFD').replace(/[̀-ͯ]/g, '')
                          .replace(/[^a-z0-9']+/g, ' ').trim() + ' ';
  for (const lang of SUPPORTED) {
    for (const w of WORD_MARKERS[lang]) {
      const needle = w.includes(' ') ? w : ' ' + w + ' ';
      if (flat.includes(needle)) scores[lang] += 2;
    }
  }

  const ranked = SUPPORTED.slice().sort((a, b) => scores[b] - scores[a]);
  const top = ranked[0], second = ranked[1];
  // A single weak hit decides nothing, and a near-tie between pt and es is the
  // case most likely to be wrong. Both fall back rather than guess.
  // Two ways to be sure, and they cover different shapes of message:
  //   - unopposed: any evidence at all for exactly one language, none for the
  //     others. "Ola, procuro casa em Cascais" is short but unambiguous.
  //   - contested: enough evidence AND a clear margin. This is the pt/es case,
  //     where both score and the winner has to actually win.
  // Everything else falls back to the configured default rather than guessing.
  const unopposed = scores[top] >= 2 && scores[second] === 0;
  const contested = scores[top] >= 4 && (scores[top] - scores[second]) >= 4;
  const confident = unopposed || contested;
  return out(confident ? top : null, scores, confident);
}

// pickMessage(messages, lang, fallbackLang) -> string|null
//
// `messages` is the config map, e.g. {pt: '...', en: '...', es: '...'}. Resolution
// order is: detected language -> the client's configured default -> English ->
// whatever single string was configured. Every step is a fixed string; nothing
// here is generated.
function pickMessage(messages, lang, fallbackLang) {
  if (typeof messages === 'string') return messages;          // legacy single string
  if (!messages || typeof messages !== 'object') return null;
  const order = [lang, fallbackLang, 'en', 'pt'];
  for (const k of order) {
    if (k && typeof messages[k] === 'string' && messages[k].trim()) return messages[k];
  }
  const first = Object.values(messages).find(v => typeof v === 'string' && v.trim());
  return first || null;
}

// Convenience: resolve a named system message for a lead's text in one call.
// `cfg` is client_automations.config.
function systemMessage(cfg, name, leadText) {
  const c = cfg || {};
  const det = detectLanguage(leadText);
  const fallback = c.default_language
    || (Array.isArray(c.languages) && c.languages.length ? c.languages[0] : 'en');
  const bag = (c.system_messages || {})[name];
  const picked = pickMessage(bag, det.lang, fallback);
  return {
    text: picked || c.handoff_note || null,
    lang: det.lang || fallback,
    detected: det.lang,
    confident: det.confident,
    scores: det.scores,
  };
}


// Convergence point for every post-parse path. Downstream nodes read
// $('DecideEscalation') rather than $('ParseClaude'), because either the first
// parse OR the guard retry may have produced the item.
const j   = $input.first().json;
const a   = $('AfterLead').first().json;
const cfg = a.config || {};
const p   = j.parsed || null;
const sl  = $('ProposeSlots').first().json;
const mc  = $('ResolveBooking').first().json;   // the VERIFIED booking state, not the stored claim

const HANDOFF = systemMessage(cfg, 'handoff', a.body);

// ---------------------------------------------------------------------------
// A booking found cancelled or missing THIS TURN always escalates, and the
// lead is ALWAYS told, in a fixed string. On 2026-09-12 the model escalated
// this case itself with a perfectly good reason -- and the escalation path
// discarded its reply and sent the generic handoff note, so a lead who asked
// "esta tudo confirmado?" was told a colleague would be in touch and nothing
// else. They still believed they had a meeting. A real buyer turns up.
//
// Deterministic, like every other system message: not the model's reply
// (which is discarded on escalation by design) and not a prompt instruction
// (which is the layer that fails). `{when}` is rendered here, in the lead's
// language and the client's zone. The fixed text is overridable per client via
// config.system_messages.booking_retired; these are the defaults.
// ---------------------------------------------------------------------------
const RETIRED_DEFAULT = {
  pt: 'A marcação que tínhamos para {when} já não está na nossa agenda. Peço desculpa pelo incómodo. Um colega da equipa vai entrar em contacto consigo em breve para combinar uma nova hora.',
  en: 'The appointment we had booked for {when} is no longer in our diary. I am sorry for the inconvenience. A member of our team will be in touch with you shortly to arrange a new time.',
  es: 'La cita que teníamos para {when} ya no está en nuestra agenda. Disculpe las molestias. Un compañero del equipo se pondrá en contacto con usted en breve para acordar una nueva hora.',
};
const rb = mc.bookingRetired || null;
const retiredGone = !!rb && (mc.bookingCheck === 'cancelled' || mc.bookingCheck === 'missing');
let RETIRED_NOTE = null;
if (retiredGone) {
  const bag = Object.assign({}, cfg.system_messages || {});
  if (!bag.booking_retired) bag.booking_retired = RETIRED_DEFAULT;
  const R = systemMessage(Object.assign({}, cfg, { system_messages: bag }), 'booking_retired', a.body);
  const lang = R.lang || 'pt';
  const zone = rb.zone || cfg.timezone || 'Europe/Lisbon';
  const city = zone.indexOf('/') !== -1 ? zone.split('/')[1].replace(/_/g, ' ') : zone;
  const FMT  = { pt: "cccc, d 'de' LLLL 'às' HH:mm", es: "cccc d 'de' LLLL 'a las' HH:mm", en: "cccc d LLLL 'at' HH:mm" };
  const ZONE = { pt: 'hora de ' + city, es: 'hora de ' + city, en: city + ' time' };
  const dt = DateTime.fromISO(String(rb.startUtc || ''), { zone: 'utc' }).setZone(zone).setLocale(lang);
  const when = dt.isValid
    ? dt.toFormat(FMT[lang] || FMT.en) + ' (' + (ZONE[lang] || ZONE.en) + ')'
    : String(rb.local || rb.startUtc || '');
  RETIRED_NOTE = String(R.text || RETIRED_DEFAULT[lang] || RETIRED_DEFAULT.en).replace('{when}', when);
}

const reasons = [];
if (!j.ok) {
  // "Claude fails twice or returns unparseable JSON" is an escalation trigger
  // in its own right (§5.4). The lead still gets the handoff note.
  reasons.push(j.errorType === 'bad_reply' ? 'bad_reply_twice' : ('claude_failed:' + j.errorType));
} else {
  if (p.needs_human === true) {
    reasons.push('needs_human' + (p.escalation_reason ? ':' + p.escalation_reason : ''));
  }
  // High-value threshold, from config -- not hardcoded.
  const thr = Number(cfg.high_value_threshold_eur || 0);
  const hi = Math.max(Number(p.budget_max || 0), Number(p.budget_min || 0));
  if (thr > 0 && hi >= thr) reasons.push('high_value:' + hi + '>=' + thr);

  // §9.9: a lead asking to book when we have nothing to offer must not be left
  // with a warm nothing. Gated on wants_booking -- free/busy runs on EVERY
  // inbound message, so an unrelated question during a calendar outage must
  // not escalate the lead. slotError covers the guarded cases (bad or absent
  // calendar id, non-2xx, malformed body), which are indistinguishable from a
  // genuinely free calendar at the wire level.
  if (p.wants_booking === true && !(sl.slotLines || []).length) {
    reasons.push(sl.slotError ? 'no_availability:' + sl.slotError
                              : 'no_availability:window_full');
  }
}
// Whatever the model decided, a vanished booking is a human's to reconcile.
if (retiredGone) reasons.push('booking_retired:' + mc.bookingCheck);

return [{ json: { ...j,
  escalating: reasons.length > 0,
  escalationReasons: reasons,
  escalationReason: reasons.join(' | ') || null,
  // Fixed config string, picked by deterministic language rules from the
  // lead's own words. If detection is unsure it falls back to the client's
  // configured default -- never to a guess, and never to a model.
  handoffNote: HANDOFF.text || 'A member of the team will follow up personally.',
  handoffLang: HANDOFF.lang,
  handoffLangDetected: HANDOFF.detected,
  escalateTo: cfg.escalate_to || null,
  // If the parse failed there is no reply to send -- the handoff note is a
  // fixed config string and does not depend on Claude having succeeded (§8).
  replyText: (p && p.reply) ? p.reply : null,
  // Escalation wins over booking (§3): a lead who is both escalating AND
  // confirming a time is exactly the case a human should be holding.
  bookReady: mc.bookingIntent === 'confirm' && reasons.length === 0,
  bookingIntent: mc.bookingIntent,
  bookingSlot: mc.bookingSlot || null,
  bookingEventId: mc.bookingEventId || null,
  bookingMatchedBy: mc.bookingMatchedBy || null,
  existingBooking: mc.existingBooking || null,
  // The handoff note alone is the right message for a lead who asked for a
  // human. It is the WRONG message for a lead who asked to book and hit an
  // empty calendar -- that one needs the honest answer as well as the note.
  handoffBody: (retiredGone && RETIRED_NOTE)
    ? RETIRED_NOTE
    : (reasons.length === 1 && reasons[0].indexOf('no_availability') === 0 && p && p.reply)
      ? p.reply + '\n\n' + (HANDOFF.text || 'A member of the team will follow up personally.')
      : (HANDOFF.text || 'A member of the team will follow up personally.'),
  bookingRetiredNote: RETIRED_NOTE,
} }];

const d = $('AfterBooking').first().json;
const res = $input.first().json;                 // HTTP envelope (lesson 9)
const ok = res.statusCode >= 200 && res.statusCode < 300;
const b = res.body || {};
return [{ json: { ...d, handoffOk: ok, handoffSid: ok ? (b.sid || null) : null,
                  handoffErrorCode: ok ? null : (b.code || res.statusCode) } }];

// THE TRAP (§8): the operator notification and the lead reply ride the SAME
// Twilio sandbox. If the sandbox is why the reply failed, this notification
// fails too -- the alert dies with the thing it is alerting about. So its
// failure is recorded explicitly, at critical severity, rather than inferred.
const h   = $('AfterHandoff').first().json;
const res = $input.first().json;
const ok  = res.statusCode >= 200 && res.statusCode < 300;
const b   = res.body || {};
const noTarget = !h.escalateTo;
return [{ json: { ...h,
  notifyAttempted: !noTarget,
  notifyOk: ok && !noTarget,
  notifySid: (ok && !noTarget) ? (b.sid || null) : null,
  notifyErrorCode: noTarget ? 'no_escalate_to_configured' : (ok ? null : (b.code || res.statusCode)),
  notifyErrorMessage: noTarget ? 'config.escalate_to is not set'
                               : (ok ? null : String(b.message || '').slice(0, 200)),
} }];

const j = $('AfterNotify').first().json;
const ev = $input.first().json;
const lu = $('AfterLeadUpdate').first().json;
const notifyFailed = !j.notifyOk;

// An escalation is not automatically a healthy run.
//
// D5 drill 1 broke the Anthropic credential: every lead was escalated, the
// handoff note went out correctly -- and every run was logged `success`. A
// total model outage was indistinguishable in `automation_runs` from a normal
// day of leads asking for a human. Metrics derived from those rows would have
// shown a healthy day.
//
// So the row records WHY it escalated. A lead asking for a person is a
// success; a dependency being down is not.
const SYSTEM_REASONS = /^(claude_failed|bad_reply_twice|booking_failed|no_availability|media_unprocessable)/;
const systemFailure = (j.escalationReasons || []).some(r => SYSTEM_REASONS.test(String(r)));
// Present only when the WhatsApp notify failed and the email fallback ran.
// Referencing a node that did not execute throws, so this is guarded -- and
// the guard must be declared before it is used, which an earlier patch of this
// file got wrong and broke every escalation until the next message.
let ea = null; try { ea = $('AfterEmailAlert').first().json; } catch (e) { ea = null; }
return [{ json: { run: {
  client_automation_id: j.clientAutomationId,
  status: (notifyFailed || systemFailure) ? 'error' : 'success',
  started_at: j.startedAt,
  finished_at: new Date().toISOString(),
  duration_ms: Math.max(0, new Date() - new Date(j.startedAt)),
  error_type: systemFailure ? String((j.escalationReasons || []).find(r => SYSTEM_REASONS.test(String(r))))
            : (notifyFailed ? 'escalation_notify_failed' : null),
  error_message: notifyFailed ? ('operator not reached: ' + j.notifyErrorCode + ' ' + (j.notifyErrorMessage || ''))
               : (systemFailure ? ('escalated by a system failure: ' + (j.escalationReason || '')) : null),
  payload: { checkpoint: 'B3', escalated: true, system_failure: systemFailure, reasons: j.escalationReasons,
             handoff_lang: j.handoffLang || null,
             email_alert_ok: ea ? ea.emailAlertOk : null,
             email_alert_error: ea ? ea.emailAlertError : null,
             handoff_sent: j.handoffOk, operator_notified: j.notifyOk,
             was_guard_retry: !!j.wasGuardRetry, events_status: ev.statusCode,
             model: j.modelUsed || null, claude_ms: j.durationMs || null,
             stage_after: lu.stageAfter, fields_changed: (lu.changed || []).length,
             lead_update_ok: lu.leadUpdateOk },
} } }];

// ============================================================================
// Slot engine — shared source. Embedded verbatim into the ProposeSlots Code
// node, and unit-tested standalone against non-Lisbon timezones.
//
// §4: the test environment has calendar, config and cron all agreeing on
// Europe/Lisbon. That agreement HIDES timezone bugs rather than revealing them,
// so nothing here may hardcode a zone and every case below is exercised against
// Europe/Madrid (+1 vs Lisbon) as well.
//
// Everything is computed and stored in UTC. The client timezone is used at
// exactly three edges: filtering to working hours, formatting for the lead, and
// setting the calendar event's zone.
// ============================================================================
// ---------------------------------------------------------------------------
// Google free/busy returns HTTP 200 for a calendar it cannot read, with an
// `errors` array and an EMPTY `busy` list. An unreachable or misconfigured
// calendar is therefore indistinguishable from a totally free one unless the
// errors array is read. Unguarded, that offers every slot in the window as
// available. Verified against the live API on 2026-09-03.
function readFreeBusy(httpResponse, calendarId) {
  const res = httpResponse || {};
  const code = res.statusCode;
  if (!(code >= 200 && code < 300)) {
    return { ok: false, busy: [], error: 'freebusy_http_' + code };
  }
  const cals = (res.body && res.body.calendars) || null;
  if (!cals) return { ok: false, busy: [], error: 'freebusy_malformed' };
  const entry = cals[calendarId];
  if (!entry) return { ok: false, busy: [], error: 'freebusy_calendar_absent' };
  if (Array.isArray(entry.errors) && entry.errors.length) {
    const reason = entry.errors.map(e => e.reason || 'unknown').join(',');
    return { ok: false, busy: [], error: 'freebusy_calendar_error:' + reason };
  }
  return { ok: true, busy: Array.isArray(entry.busy) ? entry.busy : [], error: null };
}

// ---------------------------------------------------------------------------
// A lightweight, workflow-side date HINT.
//
// The slots must be in Claude's prompt before it replies, and Checkpoint C2
// needs the workflow to know exactly which slots were offered -- so the model
// cannot be the one choosing them. That rules out taking the preferred day from
// the model's output on the same turn.
//
// This produces a CANDIDATE date only. Every guard in computeSlots still
// applies, and anything unrecognised or invalid falls back silently to
// spreading. The worst failure is an uneven spread, never a wrong or
// unavailable time.
const WEEKDAYS = {
  1: ['segunda', 'monday', 'lunes'],
  2: ['terca', 'tuesday', 'martes'],
  3: ['quarta', 'wednesday', 'miercoles'],
  4: ['quinta', 'thursday', 'jueves'],
  5: ['sexta', 'friday', 'viernes'],
  6: ['sabado', 'saturday'],
  7: ['domingo', 'sunday'],
};
function extractPreferredDate(text, tz, nowISO) {
  if (!text) return null;
  // Strip diacritics first. A JS \\b after "ã" never matches, because an accented
  // character is not a word character -- so "amanhã?" failed while "tomorrow"
  // worked. Normalising also removes the need to enumerate accented variants.
  const t = String(text).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  const now = DateTime.fromISO(nowISO, { zone: 'utc' }).setZone(tz);

  if (/\b(hoje|today|hoy)\b/.test(t)) return now.toFormat('yyyy-LL-dd');
  if (/\b(amanha|tomorrow|manana)\b/.test(t)) {
    return now.plus({ days: 1 }).toFormat('yyyy-LL-dd');
  }
  // "dia 12", "no dia 12 de setembro". Without this, "sabado dia 12" matched
  // only the weekday and resolved to the NEXT Saturday -- so a request for the
  // 12th was answered with slots for the 5th, and the model then invented times
  // for the day it had been asked about. Checked before the weekday branch for
  // exactly that reason.
  const dia = t.match(/\bdia\s+(\d{1,2})\b/);
  if (dia) {
    const day = Number(dia[1]);
    for (let i = 0; i < 400; i++) {
      const d = now.plus({ days: i });
      if (d.day === day) return d.toFormat('yyyy-LL-dd');
    }
    return null;
  }

  // Explicit dd/mm or dd-mm, year optional.
  const m = t.match(/\b(\d{1,2})[\/\-.](\d{1,2})(?:[\/\-.](\d{2,4}))?\b/);
  if (m) {
    const day = Number(m[1]), mon = Number(m[2]);
    let year = m[3] ? Number(m[3]) : now.year;
    if (year < 100) year += 2000;
    const d = DateTime.fromObject({ year, month: mon, day }, { zone: tz });
    if (d.isValid) {
      // A bare dd/mm already past this year means next year.
      return (!m[3] && d < now.startOf('day') ? d.plus({ years: 1 }) : d).toFormat('yyyy-LL-dd');
    }
    return null;
  }
  for (const [wd, names] of Object.entries(WEEKDAYS)) {
    if (names.some(n => t.includes(n))) {
      const target = Number(wd);
      // "next <weekday>" means the coming one; today does not count, because a
      // same-day request will fail min_hours_notice anyway.
      let d = now.plus({ days: 1 }).startOf('day');
      for (let i = 0; i < 7; i++) {
        if (d.weekday === target) return d.toFormat('yyyy-LL-dd');
        d = d.plus({ days: 1 });
      }
    }
  }
  return null;
}

function computeSlots(opts) {
  const {
    nowISO,                    // UTC instant, ISO
    tz,                        // IANA zone from client config -- never a literal
    workingHours,              // {start:'09:00', end:'19:00', days:[1..6]}
    bookingWindowDays,
    minHoursNotice,
    durationMinutes,
    busy,                      // [{start,end}] ISO UTC, from free/busy
    maxSlots,
    preferDate,                // optional 'YYYY-MM-DD' in tz; soft preference
    slotStepMinutes,
  } = opts;

  const step = slotStepMinutes || 60;
  const max = maxSlots || 3;
  const now = DateTime.fromISO(nowISO, { zone: 'utc' });
  if (!now.isValid) throw new Error('bad nowISO');

  const zone = tz;
  const earliest = now.plus({ hours: minHoursNotice });     // never "in 20 minutes"
  const windowEnd = now.plus({ days: bookingWindowDays });

  const busyIv = (busy || []).map(b => ({
    s: DateTime.fromISO(b.start, { zone: 'utc' }),
    e: DateTime.fromISO(b.end, { zone: 'utc' }),
  })).filter(x => x.s.isValid && x.e.isValid);

  const overlaps = (s, e) => busyIv.some(b => s < b.e && e > b.s);

  const [sh, sm] = String(workingHours.start).split(':').map(Number);
  const [eh, em] = String(workingHours.end).split(':').map(Number);
  const allowedDays = new Set(workingHours.days || [1, 2, 3, 4, 5, 6]);

  // Walk calendar days in the CLIENT's zone, not UTC -- a day boundary in
  // Lisbon is not a day boundary in Madrid.
  const perDay = [];
  const perDayAll = [];
  let cursor = now.setZone(zone).startOf('day');
  const lastDay = windowEnd.setZone(zone).endOf('day');

  while (cursor <= lastDay) {
    if (allowedDays.has(cursor.weekday)) {          // Luxon: 1=Mon .. 7=Sun
      const dayStart = cursor.set({ hour: sh, minute: sm, second: 0, millisecond: 0 });
      const dayEnd = cursor.set({ hour: eh, minute: em, second: 0, millisecond: 0 });
      const free = [];
      let eligible = 0;
      // Re-derive from the day, so a DST transition inside the day is applied
      // by Luxon rather than by adding fixed offsets.
      for (let t = dayStart; t.plus({ minutes: durationMinutes }) <= dayEnd; t = t.plus({ minutes: step })) {
        const sUtc = t.toUTC();
        const eUtc = t.plus({ minutes: durationMinutes }).toUTC();
        if (sUtc < earliest) continue;              // past, or inside notice period
        if (eUtc > windowEnd) continue;             // beyond the booking window
        eligible++;                                 // would be offerable if free
        if (overlaps(sUtc, eUtc)) continue;         // busy
        free.push({
          startUtc: sUtc.toISO(),
          endUtc: eUtc.toISO(),
          startLocal: t.toISO(),
          dateLocal: t.toFormat('yyyy-LL-dd'),
          timeLocal: t.toFormat('HH:mm'),
          zone,
        });
      }
      // `eligible` counts slots that clear the past/notice/window tests but
      // ignores busy. It is the only way to tell "that day is booked up" from
      // "that day is too soon" -- and saying the wrong one is asserting a cause
      // the system does not actually know.
      if (eligible || free.length) {
        perDayAll.push({ date: cursor.toFormat('yyyy-LL-dd'), free, eligible });
      }
      if (free.length) perDay.push({ date: cursor.toFormat('yyyy-LL-dd'), free });
    }
    cursor = cursor.plus({ days: 1 });
  }

  // ---------------------------------------------------------------------
  // preferDate comes from the MODEL (it extracts "quinta-feira" from the
  // lead's message), so it is validated before it is allowed to influence
  // anything. It affects ORDERING and INCLUSION only -- never eligibility.
  // A slot that is not genuinely free can never be surfaced by preferring it.
  // Any failed check falls back silently to spreading.
  // ---------------------------------------------------------------------
  let preferStatus = 'none';
  let prefer = null;
  if (preferDate) {
    preferStatus = 'invalid';
    const d = DateTime.fromISO(String(preferDate), { zone });
    if (d.isValid) {
      const dayKey = d.toFormat('yyyy-LL-dd');
      const dayStartUtc = d.startOf('day').toUTC();
      const dayEndUtc = d.endOf('day').toUTC();
      const inWindow = dayEndUtc >= now && dayStartUtc <= windowEnd;
      const notPast = dayEndUtc > now;
      const afterNotice = dayEndUtc > earliest;
      const workingDay = allowedDays.has(d.weekday);
      // Each failure gets its own status. They all fall back to spreading, but
      // the reply should be able to say WHICH thing was true -- "we are closed
      // on Sundays" and "that is too soon" are different sentences to a lead,
      // and picking the wrong one is an invented fact.
      if (!workingDay) preferStatus = 'closed_day';
      else if (!notPast || !afterNotice) preferStatus = 'too_soon';
      else if (!inWindow) preferStatus = 'out_of_window';
      if (inWindow && notPast && afterNotice && workingDay) {
        prefer = dayKey;
        // Valid, but the day may yield nothing -- and there are two different
        // reasons for that. "Full" means the calendar is genuinely blocked;
        // "too soon" means every slot on that day sits inside min_hours_notice.
        // Reporting one as the other is asserting a cause we did not check.
        if (perDay.some(x => x.date === dayKey)) {
          preferStatus = 'used';
        } else {
          const rec = perDayAll.find(x => x.date === dayKey);
          preferStatus = (rec && rec.eligible > 0) ? 'full' : 'too_soon';
        }
      }
    }
  }

  const out = [];
  if (prefer && preferStatus === 'used') {
    // Listen to what was asked for: take up to 2 from the requested day, then
    // spread the remainder, so an alternative is still offered.
    const day = perDay.find(x => x.date === prefer);
    for (const s of day.free.slice(0, Math.min(2, max))) out.push(s);
  }
  for (const d of perDay) {
    if (out.length >= max) break;
    if (prefer && d.date === prefer) continue;          // already taken from
    out.push(d.free[0]);
  }
  // If only one day has availability at all, fill from it rather than
  // under-offering.
  if (out.length < max && perDay.length === 1) {
    for (const s of perDay[0].free) {
      if (out.length >= max) break;
      if (!out.some(o => o.startUtc === s.startUtc)) out.push(s);
    }
  }
  return { slots: out, preferDate: prefer,
           preferRequested: preferDate || null, preferStatus };
}

// ============================================================================
// Checkpoint C2 — does this message confirm one of the slots we offered?
//
// The WORKFLOW decides, for the same reason it chose the slots in C1: an event
// is about to be created, and "which one did they mean" must be answerable from
// stored data rather than from a model's paraphrase. The model still phrases
// the outcome -- it is just told the outcome rather than asked for it.
//
// Deciding this before the Claude call, rather than after, is what keeps the
// booking turn to ONE model call: by the time Claude writes, the event either
// exists or it does not, so it never confirms a booking that failed.
//
// The bias is deliberate and one-directional: when in doubt, do NOT book. An
// ambiguous message costs the lead one clarifying question. A wrong match puts
// a real appointment in a real agent's calendar at a time nobody agreed to.
// ============================================================================
const AFFIRMATIVE = /\b(sim|yes|si|ok|okay|claro|perfeito|perfect|combinado|pode ser|works|great|otimo|vale|de acuerdo)\b/;

// "segunda" is deliberately absent from the ordinals. In Portuguese it is both
// "the second one" and "Monday", and a booking is not the place to guess.
const ORDINALS = [
  { rx: /\b(primeir[oa]|first|primer[oa]|1o|1a|1º|1ª)\b/, idx: 0 },
  { rx: /\b(terceir[oa]|third|tercer[oa]|3o|3a)\b/, idx: 2 },
  { rx: /\b(ultim[oa]|last)\b/, idx: -1 },
];

function matchConfirmation(text, storedSlots, tz, nowISO) {
  const out = (status, slot, by) => ({ status, slot: slot || null, matchedBy: by || null });
  const slots = Array.isArray(storedSlots) ? storedSlots : [];
  if (!slots.length) return out('no_offer');
  if (!text) return out('none');

  const t = String(text).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

  // Describe each offered slot in the client's zone, so every comparison below
  // is against what the lead was actually shown.
  const desc = slots.map((s, i) => {
    const d = DateTime.fromISO(s.startUtc).setZone(s.zone || tz);
    return { i, slot: s, weekday: d.weekday, date: d.toFormat('yyyy-LL-dd'),
             day: d.day, month: d.month, hour: d.hour, minute: d.minute };
  });

  const signals = [];
  let pool = desc;
  const narrow = (fn, name) => {
    const next = pool.filter(fn);
    if (next.length) { pool = next; signals.push(name); }
    return next.length;
  };

  // --- an explicit clock time: "9h", "09:00", "as 10", "10h30" ---------------
  const hours = new Set();
  let m;
  const explicitRx = /\b(\d{1,2})[:h](\d{2})\b|\b(\d{1,2})\s*h\b|\bas\s+(\d{1,2})\b|\bat\s+(\d{1,2})\b/g;
  while ((m = explicitRx.exec(t)) !== null) {
    const h = Number(m[1] || m[3] || m[4] || m[5]);
    if (h >= 0 && h <= 23) hours.add(h);
  }
  if (hours.size) {
    // Same rule as an unoffered weekday, and it matters more here: with a
    // single slot on offer, "as 14:00 pode ser?" would otherwise fall through
    // to the affirmative branch and book the 09:00 nobody asked for.
    if (!desc.some(x => hours.has(x.hour))) return out('none', null, 'time_not_offered');
    narrow(x => hours.has(x.hour), 'time');
  }

  // --- a weekday name -------------------------------------------------------
  const wanted = new Set();
  for (const [wd, names] of Object.entries(WEEKDAYS)) {
    if (names.some(n => t.includes(n))) wanted.add(Number(wd));
  }
  if (wanted.size) {
    // A weekday we never offered is a NEW request, not a confirmation. C1's
    // preferDate path owns that; booking must keep its hands off it.
    if (!desc.some(x => wanted.has(x.weekday))) return out('none', null, 'weekday_not_offered');
    narrow(x => wanted.has(x.weekday), 'weekday');
  }

  // --- "dia 10", or an explicit 10/09 --------------------------------------
  const dm = t.match(/\b(\d{1,2})[\/\-.](\d{1,2})\b/);
  if (dm) {
    const day = Number(dm[1]), mon = Number(dm[2]);
    if (!desc.some(x => x.day === day && x.month === mon)) return out('none', null, 'date_not_offered');
    narrow(x => x.day === day && x.month === mon, 'date');
  } else {
    const dia = t.match(/\bdia\s+(\d{1,2})\b/);
    if (dia) {
      const day = Number(dia[1]);
      if (!desc.some(x => x.day === day)) return out('none', null, 'date_not_offered');
      narrow(x => x.day === day, 'day_of_month');
    }
  }

  // --- "a primeira", "the last one" ----------------------------------------
  if (pool.length > 1) {
    for (const o of ORDINALS) {
      if (o.rx.test(t)) {
        const target = o.idx === -1 ? desc[desc.length - 1] : desc[o.idx];
        if (target && pool.includes(target)) { pool = [target]; signals.push('ordinal'); }
        break;
      }
    }
  }

  if (signals.length && pool.length === 1) {
    return out('matched', pool[0].slot, signals.join('+'));
  }
  if (signals.length && pool.length > 1) {
    return out('ambiguous', null, signals.join('+'));
  }

  // --- a bare "sim" only works when there is nothing to be ambiguous about ---
  if (AFFIRMATIVE.test(t)) {
    if (desc.length === 1) return out('matched', desc[0].slot, 'affirmative_single_offer');
    return out('ambiguous', null, 'affirmative_multiple_offers');
  }
  return out('none');
}
// ---------------------------------------------------------------------------
// Choose the slots. The WORKFLOW picks them, never the model: Checkpoint C2
// matches the lead's confirmation against exactly what was stored here, so the
// offer has to be knowable. The model only phrases it.
// ---------------------------------------------------------------------------
const a   = $('AfterLead').first().json;
const cfg = a.config || {};
const res = $input.first().json;
const nowISO = new Date().toISOString();
const tz = cfg.timezone || 'Europe/Lisbon';

// Explicit guard on the calendar id itself, not just on the response. A missing
// or malformed id must be reported, never silently treated as "no availability"
// -- which is the same failure the free/busy errors array hides.
const calId = cfg.calendar_id;
let slotError = null;
if (!calId || typeof calId !== 'string' || calId.indexOf('@') === -1) {
  slotError = 'calendar_not_configured';
}

let fbBusy = [];
let slots = [], preferDate = null, preferRequested = null;
let preferStatus = 'none', busyCount = 0;
let offerSource = 'fresh';
if (!slotError) {
  const fb = readFreeBusy(res, calId);
  if (!fb.ok) {
    slotError = fb.error;
  } else {
    busyCount = fb.busy.length;
    fbBusy = fb.busy;
    const newPrefer = extractPreferredDate(a.body, tz, nowISO);
    preferDate = newPrefer;
    const out = computeSlots({
      nowISO, tz,
      workingHours: cfg.working_hours || { start: '09:00', end: '19:00', days: [1,2,3,4,5,6] },
      bookingWindowDays: cfg.booking_window_days || 14,
      minHoursNotice: cfg.min_hours_notice == null ? 24 : cfg.min_hours_notice,
      durationMinutes: cfg.viewing_duration_minutes || 60,
      busy: fb.busy,
      maxSlots: 3,
      preferDate,
      slotStepMinutes: 60,
    });
    // -------------------------------------------------------------------
    // An offer already on the table stays on the table.
    //
    // Without this, any unrelated message ("tem estacionamento?") recomputed a
    // fresh spread and OVERWROTE the stored proposals -- so a lead who had been
    // offered Thursday 09:00 and 10:00 could reply "the Thursday one" against a
    // stored set that no longer contained Thursday. Checkpoint C2 matches
    // confirmations against what is stored, so a moving offer is unmatchable.
    //
    // The stored offer is re-validated every turn: anything now in the past,
    // inside the notice period, or newly busy is dropped. A genuinely NEW date
    // request supersedes it.
    const prior = (a.priorQualification || {}).proposed_slots;

    // A requested day only SUPERSEDES a standing offer if it is actually
    // usable. Testing `newPrefer` alone threw away a live Thursday offer the
    // moment the lead asked "e no domingo?" -- we cannot do Sundays, so the
    // lead lost the times they were considering and the model apologised for
    // "the earlier confusion". preferDate influences ordering and inclusion
    // only; it must not change which offer is on the table either.
    const preferUsable = out.preferStatus === 'used';
    const supersede = preferUsable && (!prior || prior.prefer_date !== newPrefer);

    let reused = null;
    if (prior && !supersede) {
      const ageMs = Date.now() - new Date(prior.at).getTime();
      if (ageMs < 24 * 3600 * 1000) {                 // §5: proposals go stale at 24h
        const earliest = DateTime.fromISO(nowISO, { zone: 'utc' })
          .plus({ hours: cfg.min_hours_notice == null ? 24 : cfg.min_hours_notice });
        const stillGood = (prior.slots || []).filter(s => {
          const st = DateTime.fromISO(s.startUtc), en = DateTime.fromISO(s.endUtc);
          if (st < earliest) return false;
          return !fb.busy.some(b => st < DateTime.fromISO(b.end) && en > DateTime.fromISO(b.start));
        });
        if (stillGood.length) {
          reused = stillGood.map(s => ({
            startUtc: s.startUtc, endUtc: s.endUtc, startLocal: s.local, zone: s.zone,
            dateLocal: DateTime.fromISO(s.startUtc).setZone(s.zone).toFormat('yyyy-LL-dd'),
            timeLocal: DateTime.fromISO(s.startUtc).setZone(s.zone).toFormat('HH:mm'),
          }));
        }
      }
    }

    if (reused) {
      slots = reused;
      offerSource = 'reused';
      // The offer holds, but a day the lead just asked for and cannot have
      // still has to be acknowledged -- silently re-offering the same times
      // reads as not listening.
      if (newPrefer && !preferUsable) {
        preferDate = null;
        preferRequested = out.preferRequested;
        preferStatus = out.preferStatus;
      } else {
        preferDate = prior.prefer_date || null;
        preferRequested = prior.prefer_requested || prior.prefer_date || null;
        preferStatus = prior.prefer_status || 'none';
      }
    } else {
      slots = out.slots;
      preferStatus = out.preferStatus;
      preferDate = out.preferDate;
      preferRequested = out.preferRequested;
      offerSource = supersede ? 'fresh_new_date' : 'fresh';
    }
  }
}

// Human-readable lines for the prompt. The workflow writes these; the model
// restates them in the lead's language without altering the numbers.
const MONTHS = ['January','February','March','April','May','June','July',
                'August','September','October','November','December'];
const DAYS = ['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
const lines = slots.map(s => {
  const d = DateTime.fromISO(s.startUtc).setZone(s.zone);
  return `${DAYS[d.weekday-1]} ${d.day} ${MONTHS[d.month-1]} ${d.year} at ${s.timeLocal} ${s.zone.split('/')[1].replace('_',' ')} time`;
});

return [{ json: { ...a,
  slots, slotLines: lines, slotError, preferDate, preferRequested,
  preferStatus, offerSource,
  busyIntervals: busyCount,
  busy: (!slotError && typeof fbBusy !== 'undefined') ? fbBusy : [],
  freeBusyStatus: res && res.statusCode,
} }];

// ============================================================================
// Slot engine — shared source. Embedded verbatim into the ProposeSlots Code
// node, and unit-tested standalone against non-Lisbon timezones.
//
// §4: the test environment has calendar, config and cron all agreeing on
// Europe/Lisbon. That agreement HIDES timezone bugs rather than revealing them,
// so nothing here may hardcode a zone and every case below is exercised against
// Europe/Madrid (+1 vs Lisbon) as well.
//
// Everything is computed and stored in UTC. The client timezone is used at
// exactly three edges: filtering to working hours, formatting for the lead, and
// setting the calendar event's zone.
// ============================================================================
// ---------------------------------------------------------------------------
// Google free/busy returns HTTP 200 for a calendar it cannot read, with an
// `errors` array and an EMPTY `busy` list. An unreachable or misconfigured
// calendar is therefore indistinguishable from a totally free one unless the
// errors array is read. Unguarded, that offers every slot in the window as
// available. Verified against the live API on 2026-09-03.
function readFreeBusy(httpResponse, calendarId) {
  const res = httpResponse || {};
  const code = res.statusCode;
  if (!(code >= 200 && code < 300)) {
    return { ok: false, busy: [], error: 'freebusy_http_' + code };
  }
  const cals = (res.body && res.body.calendars) || null;
  if (!cals) return { ok: false, busy: [], error: 'freebusy_malformed' };
  const entry = cals[calendarId];
  if (!entry) return { ok: false, busy: [], error: 'freebusy_calendar_absent' };
  if (Array.isArray(entry.errors) && entry.errors.length) {
    const reason = entry.errors.map(e => e.reason || 'unknown').join(',');
    return { ok: false, busy: [], error: 'freebusy_calendar_error:' + reason };
  }
  return { ok: true, busy: Array.isArray(entry.busy) ? entry.busy : [], error: null };
}

// ---------------------------------------------------------------------------
// A lightweight, workflow-side date HINT.
//
// The slots must be in Claude's prompt before it replies, and Checkpoint C2
// needs the workflow to know exactly which slots were offered -- so the model
// cannot be the one choosing them. That rules out taking the preferred day from
// the model's output on the same turn.
//
// This produces a CANDIDATE date only. Every guard in computeSlots still
// applies, and anything unrecognised or invalid falls back silently to
// spreading. The worst failure is an uneven spread, never a wrong or
// unavailable time.
const WEEKDAYS = {
  1: ['segunda', 'monday', 'lunes'],
  2: ['terca', 'tuesday', 'martes'],
  3: ['quarta', 'wednesday', 'miercoles'],
  4: ['quinta', 'thursday', 'jueves'],
  5: ['sexta', 'friday', 'viernes'],
  6: ['sabado', 'saturday'],
  7: ['domingo', 'sunday'],
};
function extractPreferredDate(text, tz, nowISO) {
  if (!text) return null;
  // Strip diacritics first. A JS \\b after "ã" never matches, because an accented
  // character is not a word character -- so "amanhã?" failed while "tomorrow"
  // worked. Normalising also removes the need to enumerate accented variants.
  const t = String(text).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  const now = DateTime.fromISO(nowISO, { zone: 'utc' }).setZone(tz);

  if (/\b(hoje|today|hoy)\b/.test(t)) return now.toFormat('yyyy-LL-dd');
  if (/\b(amanha|tomorrow|manana)\b/.test(t)) {
    return now.plus({ days: 1 }).toFormat('yyyy-LL-dd');
  }
  // "dia 12", "no dia 12 de setembro". Without this, "sabado dia 12" matched
  // only the weekday and resolved to the NEXT Saturday -- so a request for the
  // 12th was answered with slots for the 5th, and the model then invented times
  // for the day it had been asked about. Checked before the weekday branch for
  // exactly that reason.
  const dia = t.match(/\bdia\s+(\d{1,2})\b/);
  if (dia) {
    const day = Number(dia[1]);
    for (let i = 0; i < 400; i++) {
      const d = now.plus({ days: i });
      if (d.day === day) return d.toFormat('yyyy-LL-dd');
    }
    return null;
  }

  // Explicit dd/mm or dd-mm, year optional.
  const m = t.match(/\b(\d{1,2})[\/\-.](\d{1,2})(?:[\/\-.](\d{2,4}))?\b/);
  if (m) {
    const day = Number(m[1]), mon = Number(m[2]);
    let year = m[3] ? Number(m[3]) : now.year;
    if (year < 100) year += 2000;
    const d = DateTime.fromObject({ year, month: mon, day }, { zone: tz });
    if (d.isValid) {
      // A bare dd/mm already past this year means next year.
      return (!m[3] && d < now.startOf('day') ? d.plus({ years: 1 }) : d).toFormat('yyyy-LL-dd');
    }
    return null;
  }
  for (const [wd, names] of Object.entries(WEEKDAYS)) {
    if (names.some(n => t.includes(n))) {
      const target = Number(wd);
      // "next <weekday>" means the coming one; today does not count, because a
      // same-day request will fail min_hours_notice anyway.
      let d = now.plus({ days: 1 }).startOf('day');
      for (let i = 0; i < 7; i++) {
        if (d.weekday === target) return d.toFormat('yyyy-LL-dd');
        d = d.plus({ days: 1 });
      }
    }
  }
  return null;
}

function computeSlots(opts) {
  const {
    nowISO,                    // UTC instant, ISO
    tz,                        // IANA zone from client config -- never a literal
    workingHours,              // {start:'09:00', end:'19:00', days:[1..6]}
    bookingWindowDays,
    minHoursNotice,
    durationMinutes,
    busy,                      // [{start,end}] ISO UTC, from free/busy
    maxSlots,
    preferDate,                // optional 'YYYY-MM-DD' in tz; soft preference
    slotStepMinutes,
  } = opts;

  const step = slotStepMinutes || 60;
  const max = maxSlots || 3;
  const now = DateTime.fromISO(nowISO, { zone: 'utc' });
  if (!now.isValid) throw new Error('bad nowISO');

  const zone = tz;
  const earliest = now.plus({ hours: minHoursNotice });     // never "in 20 minutes"
  const windowEnd = now.plus({ days: bookingWindowDays });

  const busyIv = (busy || []).map(b => ({
    s: DateTime.fromISO(b.start, { zone: 'utc' }),
    e: DateTime.fromISO(b.end, { zone: 'utc' }),
  })).filter(x => x.s.isValid && x.e.isValid);

  const overlaps = (s, e) => busyIv.some(b => s < b.e && e > b.s);

  const [sh, sm] = String(workingHours.start).split(':').map(Number);
  const [eh, em] = String(workingHours.end).split(':').map(Number);
  const allowedDays = new Set(workingHours.days || [1, 2, 3, 4, 5, 6]);

  // Walk calendar days in the CLIENT's zone, not UTC -- a day boundary in
  // Lisbon is not a day boundary in Madrid.
  const perDay = [];
  const perDayAll = [];
  let cursor = now.setZone(zone).startOf('day');
  const lastDay = windowEnd.setZone(zone).endOf('day');

  while (cursor <= lastDay) {
    if (allowedDays.has(cursor.weekday)) {          // Luxon: 1=Mon .. 7=Sun
      const dayStart = cursor.set({ hour: sh, minute: sm, second: 0, millisecond: 0 });
      const dayEnd = cursor.set({ hour: eh, minute: em, second: 0, millisecond: 0 });
      const free = [];
      let eligible = 0;
      // Re-derive from the day, so a DST transition inside the day is applied
      // by Luxon rather than by adding fixed offsets.
      for (let t = dayStart; t.plus({ minutes: durationMinutes }) <= dayEnd; t = t.plus({ minutes: step })) {
        const sUtc = t.toUTC();
        const eUtc = t.plus({ minutes: durationMinutes }).toUTC();
        if (sUtc < earliest) continue;              // past, or inside notice period
        if (eUtc > windowEnd) continue;             // beyond the booking window
        eligible++;                                 // would be offerable if free
        if (overlaps(sUtc, eUtc)) continue;         // busy
        free.push({
          startUtc: sUtc.toISO(),
          endUtc: eUtc.toISO(),
          startLocal: t.toISO(),
          dateLocal: t.toFormat('yyyy-LL-dd'),
          timeLocal: t.toFormat('HH:mm'),
          zone,
        });
      }
      // `eligible` counts slots that clear the past/notice/window tests but
      // ignores busy. It is the only way to tell "that day is booked up" from
      // "that day is too soon" -- and saying the wrong one is asserting a cause
      // the system does not actually know.
      if (eligible || free.length) {
        perDayAll.push({ date: cursor.toFormat('yyyy-LL-dd'), free, eligible });
      }
      if (free.length) perDay.push({ date: cursor.toFormat('yyyy-LL-dd'), free });
    }
    cursor = cursor.plus({ days: 1 });
  }

  // ---------------------------------------------------------------------
  // preferDate comes from the MODEL (it extracts "quinta-feira" from the
  // lead's message), so it is validated before it is allowed to influence
  // anything. It affects ORDERING and INCLUSION only -- never eligibility.
  // A slot that is not genuinely free can never be surfaced by preferring it.
  // Any failed check falls back silently to spreading.
  // ---------------------------------------------------------------------
  let preferStatus = 'none';
  let prefer = null;
  if (preferDate) {
    preferStatus = 'invalid';
    const d = DateTime.fromISO(String(preferDate), { zone });
    if (d.isValid) {
      const dayKey = d.toFormat('yyyy-LL-dd');
      const dayStartUtc = d.startOf('day').toUTC();
      const dayEndUtc = d.endOf('day').toUTC();
      const inWindow = dayEndUtc >= now && dayStartUtc <= windowEnd;
      const notPast = dayEndUtc > now;
      const afterNotice = dayEndUtc > earliest;
      const workingDay = allowedDays.has(d.weekday);
      // Each failure gets its own status. They all fall back to spreading, but
      // the reply should be able to say WHICH thing was true -- "we are closed
      // on Sundays" and "that is too soon" are different sentences to a lead,
      // and picking the wrong one is an invented fact.
      if (!workingDay) preferStatus = 'closed_day';
      else if (!notPast || !afterNotice) preferStatus = 'too_soon';
      else if (!inWindow) preferStatus = 'out_of_window';
      if (inWindow && notPast && afterNotice && workingDay) {
        prefer = dayKey;
        // Valid, but the day may yield nothing -- and there are two different
        // reasons for that. "Full" means the calendar is genuinely blocked;
        // "too soon" means every slot on that day sits inside min_hours_notice.
        // Reporting one as the other is asserting a cause we did not check.
        if (perDay.some(x => x.date === dayKey)) {
          preferStatus = 'used';
        } else {
          const rec = perDayAll.find(x => x.date === dayKey);
          preferStatus = (rec && rec.eligible > 0) ? 'full' : 'too_soon';
        }
      }
    }
  }

  const out = [];
  if (prefer && preferStatus === 'used') {
    // Listen to what was asked for: take up to 2 from the requested day, then
    // spread the remainder, so an alternative is still offered.
    const day = perDay.find(x => x.date === prefer);
    for (const s of day.free.slice(0, Math.min(2, max))) out.push(s);
  }
  for (const d of perDay) {
    if (out.length >= max) break;
    if (prefer && d.date === prefer) continue;          // already taken from
    out.push(d.free[0]);
  }
  // If only one day has availability at all, fill from it rather than
  // under-offering.
  if (out.length < max && perDay.length === 1) {
    for (const s of perDay[0].free) {
      if (out.length >= max) break;
      if (!out.some(o => o.startUtc === s.startUtc)) out.push(s);
    }
  }
  return { slots: out, preferDate: prefer,
           preferRequested: preferDate || null, preferStatus };
}

// ============================================================================
// Checkpoint C2 — does this message confirm one of the slots we offered?
//
// The WORKFLOW decides, for the same reason it chose the slots in C1: an event
// is about to be created, and "which one did they mean" must be answerable from
// stored data rather than from a model's paraphrase. The model still phrases
// the outcome -- it is just told the outcome rather than asked for it.
//
// Deciding this before the Claude call, rather than after, is what keeps the
// booking turn to ONE model call: by the time Claude writes, the event either
// exists or it does not, so it never confirms a booking that failed.
//
// The bias is deliberate and one-directional: when in doubt, do NOT book. An
// ambiguous message costs the lead one clarifying question. A wrong match puts
// a real appointment in a real agent's calendar at a time nobody agreed to.
// ============================================================================
const AFFIRMATIVE = /\b(sim|yes|si|ok|okay|claro|perfeito|perfect|combinado|pode ser|works|great|otimo|vale|de acuerdo)\b/;

// "segunda" is deliberately absent from the ordinals. In Portuguese it is both
// "the second one" and "Monday", and a booking is not the place to guess.
const ORDINALS = [
  { rx: /\b(primeir[oa]|first|primer[oa]|1o|1a|1º|1ª)\b/, idx: 0 },
  { rx: /\b(terceir[oa]|third|tercer[oa]|3o|3a)\b/, idx: 2 },
  { rx: /\b(ultim[oa]|last)\b/, idx: -1 },
];

function matchConfirmation(text, storedSlots, tz, nowISO) {
  const out = (status, slot, by) => ({ status, slot: slot || null, matchedBy: by || null });
  const slots = Array.isArray(storedSlots) ? storedSlots : [];
  if (!slots.length) return out('no_offer');
  if (!text) return out('none');

  const t = String(text).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

  // Describe each offered slot in the client's zone, so every comparison below
  // is against what the lead was actually shown.
  const desc = slots.map((s, i) => {
    const d = DateTime.fromISO(s.startUtc).setZone(s.zone || tz);
    return { i, slot: s, weekday: d.weekday, date: d.toFormat('yyyy-LL-dd'),
             day: d.day, month: d.month, hour: d.hour, minute: d.minute };
  });

  const signals = [];
  let pool = desc;
  const narrow = (fn, name) => {
    const next = pool.filter(fn);
    if (next.length) { pool = next; signals.push(name); }
    return next.length;
  };

  // --- an explicit clock time: "9h", "09:00", "as 10", "10h30" ---------------
  const hours = new Set();
  let m;
  const explicitRx = /\b(\d{1,2})[:h](\d{2})\b|\b(\d{1,2})\s*h\b|\bas\s+(\d{1,2})\b|\bat\s+(\d{1,2})\b/g;
  while ((m = explicitRx.exec(t)) !== null) {
    const h = Number(m[1] || m[3] || m[4] || m[5]);
    if (h >= 0 && h <= 23) hours.add(h);
  }
  if (hours.size) {
    // Same rule as an unoffered weekday, and it matters more here: with a
    // single slot on offer, "as 14:00 pode ser?" would otherwise fall through
    // to the affirmative branch and book the 09:00 nobody asked for.
    if (!desc.some(x => hours.has(x.hour))) return out('none', null, 'time_not_offered');
    narrow(x => hours.has(x.hour), 'time');
  }

  // --- a weekday name -------------------------------------------------------
  const wanted = new Set();
  for (const [wd, names] of Object.entries(WEEKDAYS)) {
    if (names.some(n => t.includes(n))) wanted.add(Number(wd));
  }
  if (wanted.size) {
    // A weekday we never offered is a NEW request, not a confirmation. C1's
    // preferDate path owns that; booking must keep its hands off it.
    if (!desc.some(x => wanted.has(x.weekday))) return out('none', null, 'weekday_not_offered');
    narrow(x => wanted.has(x.weekday), 'weekday');
  }

  // --- "dia 10", or an explicit 10/09 --------------------------------------
  const dm = t.match(/\b(\d{1,2})[\/\-.](\d{1,2})\b/);
  if (dm) {
    const day = Number(dm[1]), mon = Number(dm[2]);
    if (!desc.some(x => x.day === day && x.month === mon)) return out('none', null, 'date_not_offered');
    narrow(x => x.day === day && x.month === mon, 'date');
  } else {
    const dia = t.match(/\bdia\s+(\d{1,2})\b/);
    if (dia) {
      const day = Number(dia[1]);
      if (!desc.some(x => x.day === day)) return out('none', null, 'date_not_offered');
      narrow(x => x.day === day, 'day_of_month');
    }
  }

  // --- "a primeira", "the last one" ----------------------------------------
  if (pool.length > 1) {
    for (const o of ORDINALS) {
      if (o.rx.test(t)) {
        const target = o.idx === -1 ? desc[desc.length - 1] : desc[o.idx];
        if (target && pool.includes(target)) { pool = [target]; signals.push('ordinal'); }
        break;
      }
    }
  }

  if (signals.length && pool.length === 1) {
    return out('matched', pool[0].slot, signals.join('+'));
  }
  if (signals.length && pool.length > 1) {
    return out('ambiguous', null, signals.join('+'));
  }

  // --- a bare "sim" only works when there is nothing to be ambiguous about ---
  if (AFFIRMATIVE.test(t)) {
    if (desc.length === 1) return out('matched', desc[0].slot, 'affirmative_single_offer');
    return out('ambiguous', null, 'affirmative_multiple_offers');
  }
  return out('none');
}
// ---------------------------------------------------------------------------
// Is this message confirming one of the times we offered?
//
// Decided HERE, before the Claude call, so the booking turn stays at one model
// call: by the time Claude writes, the outcome is known, so it never confirms
// a booking that did not happen.
// ---------------------------------------------------------------------------
const p    = $input.first().json;
const cfg  = p.config || {};
const tz   = cfg.timezone || 'Europe/Lisbon';
const prior = p.priorQualification || {};
const booked = prior.booking || null;
const ps2  = prior.proposed_slots || null;

// §5: proposals go stale at 24h. A lead replying three days later is accepting
// something that may be long gone, so it is re-proposed rather than booked.
let stored = [], offerStale = false;
if (ps2 && Array.isArray(ps2.slots) && ps2.at) {
  offerStale = (Date.now() - new Date(ps2.at).getTime()) >= 24 * 3600 * 1000;
  if (!offerStale) stored = ps2.slots;
}

const m = matchConfirmation(p.body, stored, tz, new Date().toISOString());

// The busy list from THIS run's free/busy. A slot that was taken since it was
// offered must not be confirmable, and this is the first of two checks -- the
// second runs immediately before the event is created.
const busy = p.busy || [];
const isBusy = (s) => busy.some(b =>
  DateTime.fromISO(s.startUtc) < DateTime.fromISO(b.end) &&
  DateTime.fromISO(s.endUtc)   > DateTime.fromISO(b.start));

let bookingIntent = 'none', bookingSlot = null;
if (booked && booked.event_id) {
  // Idempotency (§9.7) and the reschedule rule (§9.8) share this branch: once a
  // viewing exists, nothing here creates a second one. A lead asking to move it
  // is escalated by the model, which is told the booking exists.
  bookingIntent = 'already_booked';
} else if (m.status === 'matched') {
  bookingIntent = isBusy(m.slot) ? 'taken' : 'confirm';
  bookingSlot = m.slot;
} else if (m.status === 'ambiguous') {
  bookingIntent = 'ambiguous';
} else if (offerStale && ps2) {
  bookingIntent = 'offer_stale';
}

// A Google event id must be base32hex: [a-v0-9]. A UUID with the dashes removed
// and the timestamp digits are already inside that alphabet, so the id is
// derived rather than hashed -- deterministic, collision-free, and a replayed
// confirmation therefore collides on Google's side instead of double-booking.
// ---------------------------------------------------------------------------
// The event id is derived from the SLOT, never from the lead.
//
// Two leads confirming the same time therefore generate the SAME id, and
// Google rejects the second create with 409. That conflict IS the lock:
// atomic, server-side, in the system that owns the calendar.
//
// The previous id included the lead id, so two leads produced two different
// ids and both creates succeeded -- a real double booking, twice observed.
// A re-check before creating narrows the window; it cannot close it, because
// there is no window small enough that two concurrent actors cannot both
// observe "free".
//
// Google ids are base32hex: [a-v0-9] only, 5-1024 chars.
// ---------------------------------------------------------------------------
const calKey = String(cfg.calendar_id || '').toLowerCase()
  .replace(/[^a-v0-9]/g, '').slice(0, 16);
const eventId = bookingSlot
  ? ('rv' + calKey + String(bookingSlot.startUtc).replace(/[^0-9]/g, ''))
  : null;

return [{ json: { ...p,
  bookingIntent, bookingSlot, bookingEventId: eventId,
  bookingMatchedBy: m.matchedBy, bookingMatchStatus: m.status,
  offerStale, existingBooking: booked,
} }];

// ============================================================================
// Slot engine — shared source. Embedded verbatim into the ProposeSlots Code
// node, and unit-tested standalone against non-Lisbon timezones.
//
// §4: the test environment has calendar, config and cron all agreeing on
// Europe/Lisbon. That agreement HIDES timezone bugs rather than revealing them,
// so nothing here may hardcode a zone and every case below is exercised against
// Europe/Madrid (+1 vs Lisbon) as well.
//
// Everything is computed and stored in UTC. The client timezone is used at
// exactly three edges: filtering to working hours, formatting for the lead, and
// setting the calendar event's zone.
// ============================================================================
// ---------------------------------------------------------------------------
// Google free/busy returns HTTP 200 for a calendar it cannot read, with an
// `errors` array and an EMPTY `busy` list. An unreachable or misconfigured
// calendar is therefore indistinguishable from a totally free one unless the
// errors array is read. Unguarded, that offers every slot in the window as
// available. Verified against the live API on 2026-09-03.
function readFreeBusy(httpResponse, calendarId) {
  const res = httpResponse || {};
  const code = res.statusCode;
  if (!(code >= 200 && code < 300)) {
    return { ok: false, busy: [], error: 'freebusy_http_' + code };
  }
  const cals = (res.body && res.body.calendars) || null;
  if (!cals) return { ok: false, busy: [], error: 'freebusy_malformed' };
  const entry = cals[calendarId];
  if (!entry) return { ok: false, busy: [], error: 'freebusy_calendar_absent' };
  if (Array.isArray(entry.errors) && entry.errors.length) {
    const reason = entry.errors.map(e => e.reason || 'unknown').join(',');
    return { ok: false, busy: [], error: 'freebusy_calendar_error:' + reason };
  }
  return { ok: true, busy: Array.isArray(entry.busy) ? entry.busy : [], error: null };
}

// ---------------------------------------------------------------------------
// A lightweight, workflow-side date HINT.
//
// The slots must be in Claude's prompt before it replies, and Checkpoint C2
// needs the workflow to know exactly which slots were offered -- so the model
// cannot be the one choosing them. That rules out taking the preferred day from
// the model's output on the same turn.
//
// This produces a CANDIDATE date only. Every guard in computeSlots still
// applies, and anything unrecognised or invalid falls back silently to
// spreading. The worst failure is an uneven spread, never a wrong or
// unavailable time.
const WEEKDAYS = {
  1: ['segunda', 'monday', 'lunes'],
  2: ['terca', 'tuesday', 'martes'],
  3: ['quarta', 'wednesday', 'miercoles'],
  4: ['quinta', 'thursday', 'jueves'],
  5: ['sexta', 'friday', 'viernes'],
  6: ['sabado', 'saturday'],
  7: ['domingo', 'sunday'],
};
function extractPreferredDate(text, tz, nowISO) {
  if (!text) return null;
  // Strip diacritics first. A JS \\b after "ã" never matches, because an accented
  // character is not a word character -- so "amanhã?" failed while "tomorrow"
  // worked. Normalising also removes the need to enumerate accented variants.
  const t = String(text).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  const now = DateTime.fromISO(nowISO, { zone: 'utc' }).setZone(tz);

  if (/\b(hoje|today|hoy)\b/.test(t)) return now.toFormat('yyyy-LL-dd');
  if (/\b(amanha|tomorrow|manana)\b/.test(t)) {
    return now.plus({ days: 1 }).toFormat('yyyy-LL-dd');
  }
  // Explicit dd/mm or dd-mm, year optional.
  const m = t.match(/\b(\d{1,2})[\/\-.](\d{1,2})(?:[\/\-.](\d{2,4}))?\b/);
  if (m) {
    const day = Number(m[1]), mon = Number(m[2]);
    let year = m[3] ? Number(m[3]) : now.year;
    if (year < 100) year += 2000;
    const d = DateTime.fromObject({ year, month: mon, day }, { zone: tz });
    if (d.isValid) {
      // A bare dd/mm already past this year means next year.
      return (!m[3] && d < now.startOf('day') ? d.plus({ years: 1 }) : d).toFormat('yyyy-LL-dd');
    }
    return null;
  }
  for (const [wd, names] of Object.entries(WEEKDAYS)) {
    if (names.some(n => t.includes(n))) {
      const target = Number(wd);
      // "next <weekday>" means the coming one; today does not count, because a
      // same-day request will fail min_hours_notice anyway.
      let d = now.plus({ days: 1 }).startOf('day');
      for (let i = 0; i < 7; i++) {
        if (d.weekday === target) return d.toFormat('yyyy-LL-dd');
        d = d.plus({ days: 1 });
      }
    }
  }
  return null;
}

function computeSlots(opts) {
  const {
    nowISO,                    // UTC instant, ISO
    tz,                        // IANA zone from client config -- never a literal
    workingHours,              // {start:'09:00', end:'19:00', days:[1..6]}
    bookingWindowDays,
    minHoursNotice,
    durationMinutes,
    busy,                      // [{start,end}] ISO UTC, from free/busy
    maxSlots,
    preferDate,                // optional 'YYYY-MM-DD' in tz; soft preference
    slotStepMinutes,
  } = opts;

  const step = slotStepMinutes || 60;
  const max = maxSlots || 3;
  const now = DateTime.fromISO(nowISO, { zone: 'utc' });
  if (!now.isValid) throw new Error('bad nowISO');

  const zone = tz;
  const earliest = now.plus({ hours: minHoursNotice });     // never "in 20 minutes"
  const windowEnd = now.plus({ days: bookingWindowDays });

  const busyIv = (busy || []).map(b => ({
    s: DateTime.fromISO(b.start, { zone: 'utc' }),
    e: DateTime.fromISO(b.end, { zone: 'utc' }),
  })).filter(x => x.s.isValid && x.e.isValid);

  const overlaps = (s, e) => busyIv.some(b => s < b.e && e > b.s);

  const [sh, sm] = String(workingHours.start).split(':').map(Number);
  const [eh, em] = String(workingHours.end).split(':').map(Number);
  const allowedDays = new Set(workingHours.days || [1, 2, 3, 4, 5, 6]);

  // Walk calendar days in the CLIENT's zone, not UTC -- a day boundary in
  // Lisbon is not a day boundary in Madrid.
  const perDay = [];
  const perDayAll = [];
  let cursor = now.setZone(zone).startOf('day');
  const lastDay = windowEnd.setZone(zone).endOf('day');

  while (cursor <= lastDay) {
    if (allowedDays.has(cursor.weekday)) {          // Luxon: 1=Mon .. 7=Sun
      const dayStart = cursor.set({ hour: sh, minute: sm, second: 0, millisecond: 0 });
      const dayEnd = cursor.set({ hour: eh, minute: em, second: 0, millisecond: 0 });
      const free = [];
      let eligible = 0;
      // Re-derive from the day, so a DST transition inside the day is applied
      // by Luxon rather than by adding fixed offsets.
      for (let t = dayStart; t.plus({ minutes: durationMinutes }) <= dayEnd; t = t.plus({ minutes: step })) {
        const sUtc = t.toUTC();
        const eUtc = t.plus({ minutes: durationMinutes }).toUTC();
        if (sUtc < earliest) continue;              // past, or inside notice period
        if (eUtc > windowEnd) continue;             // beyond the booking window
        eligible++;                                 // would be offerable if free
        if (overlaps(sUtc, eUtc)) continue;         // busy
        free.push({
          startUtc: sUtc.toISO(),
          endUtc: eUtc.toISO(),
          startLocal: t.toISO(),
          dateLocal: t.toFormat('yyyy-LL-dd'),
          timeLocal: t.toFormat('HH:mm'),
          zone,
        });
      }
      // `eligible` counts slots that clear the past/notice/window tests but
      // ignores busy. It is the only way to tell "that day is booked up" from
      // "that day is too soon" -- and saying the wrong one is asserting a cause
      // the system does not actually know.
      if (eligible || free.length) {
        perDayAll.push({ date: cursor.toFormat('yyyy-LL-dd'), free, eligible });
      }
      if (free.length) perDay.push({ date: cursor.toFormat('yyyy-LL-dd'), free });
    }
    cursor = cursor.plus({ days: 1 });
  }

  // ---------------------------------------------------------------------
  // preferDate comes from the MODEL (it extracts "quinta-feira" from the
  // lead's message), so it is validated before it is allowed to influence
  // anything. It affects ORDERING and INCLUSION only -- never eligibility.
  // A slot that is not genuinely free can never be surfaced by preferring it.
  // Any failed check falls back silently to spreading.
  // ---------------------------------------------------------------------
  let preferStatus = 'none';
  let prefer = null;
  if (preferDate) {
    preferStatus = 'invalid';
    const d = DateTime.fromISO(String(preferDate), { zone });
    if (d.isValid) {
      const dayKey = d.toFormat('yyyy-LL-dd');
      const dayStartUtc = d.startOf('day').toUTC();
      const dayEndUtc = d.endOf('day').toUTC();
      const inWindow = dayEndUtc >= now && dayStartUtc <= windowEnd;
      const notPast = dayEndUtc > now;
      const afterNotice = dayEndUtc > earliest;
      const workingDay = allowedDays.has(d.weekday);
      // Each failure gets its own status. They all fall back to spreading, but
      // the reply should be able to say WHICH thing was true -- "we are closed
      // on Sundays" and "that is too soon" are different sentences to a lead,
      // and picking the wrong one is an invented fact.
      if (!workingDay) preferStatus = 'closed_day';
      else if (!notPast || !afterNotice) preferStatus = 'too_soon';
      else if (!inWindow) preferStatus = 'out_of_window';
      if (inWindow && notPast && afterNotice && workingDay) {
        prefer = dayKey;
        // Valid, but the day may yield nothing -- and there are two different
        // reasons for that. "Full" means the calendar is genuinely blocked;
        // "too soon" means every slot on that day sits inside min_hours_notice.
        // Reporting one as the other is asserting a cause we did not check.
        if (perDay.some(x => x.date === dayKey)) {
          preferStatus = 'used';
        } else {
          const rec = perDayAll.find(x => x.date === dayKey);
          preferStatus = (rec && rec.eligible > 0) ? 'full' : 'too_soon';
        }
      }
    }
  }

  const out = [];
  if (prefer && preferStatus === 'used') {
    // Listen to what was asked for: take up to 2 from the requested day, then
    // spread the remainder, so an alternative is still offered.
    const day = perDay.find(x => x.date === prefer);
    for (const s of day.free.slice(0, Math.min(2, max))) out.push(s);
  }
  for (const d of perDay) {
    if (out.length >= max) break;
    if (prefer && d.date === prefer) continue;          // already taken from
    out.push(d.free[0]);
  }
  // If only one day has availability at all, fill from it rather than
  // under-offering.
  if (out.length < max && perDay.length === 1) {
    for (const s of perDay[0].free) {
      if (out.length >= max) break;
      if (!out.some(o => o.startUtc === s.startUtc)) out.push(s);
    }
  }
  return { slots: out, preferDate: prefer,
           preferRequested: preferDate || null, preferStatus };
}

// ============================================================================
// Checkpoint C2 — does this message confirm one of the slots we offered?
//
// The WORKFLOW decides, for the same reason it chose the slots in C1: an event
// is about to be created, and "which one did they mean" must be answerable from
// stored data rather than from a model's paraphrase. The model still phrases
// the outcome -- it is just told the outcome rather than asked for it.
//
// Deciding this before the Claude call, rather than after, is what keeps the
// booking turn to ONE model call: by the time Claude writes, the event either
// exists or it does not, so it never confirms a booking that failed.
//
// The bias is deliberate and one-directional: when in doubt, do NOT book. An
// ambiguous message costs the lead one clarifying question. A wrong match puts
// a real appointment in a real agent's calendar at a time nobody agreed to.
// ============================================================================
const AFFIRMATIVE = /\b(sim|yes|si|ok|okay|claro|perfeito|perfect|combinado|pode ser|works|great|otimo|vale|de acuerdo)\b/;

// "segunda" is deliberately absent from the ordinals. In Portuguese it is both
// "the second one" and "Monday", and a booking is not the place to guess.
const ORDINALS = [
  { rx: /\b(primeir[oa]|first|primer[oa]|1o|1a|1º|1ª)\b/, idx: 0 },
  { rx: /\b(terceir[oa]|third|tercer[oa]|3o|3a)\b/, idx: 2 },
  { rx: /\b(ultim[oa]|last)\b/, idx: -1 },
];

function matchConfirmation(text, storedSlots, tz, nowISO) {
  const out = (status, slot, by) => ({ status, slot: slot || null, matchedBy: by || null });
  const slots = Array.isArray(storedSlots) ? storedSlots : [];
  if (!slots.length) return out('no_offer');
  if (!text) return out('none');

  const t = String(text).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

  // Describe each offered slot in the client's zone, so every comparison below
  // is against what the lead was actually shown.
  const desc = slots.map((s, i) => {
    const d = DateTime.fromISO(s.startUtc).setZone(s.zone || tz);
    return { i, slot: s, weekday: d.weekday, date: d.toFormat('yyyy-LL-dd'),
             day: d.day, month: d.month, hour: d.hour, minute: d.minute };
  });

  const signals = [];
  let pool = desc;
  const narrow = (fn, name) => {
    const next = pool.filter(fn);
    if (next.length) { pool = next; signals.push(name); }
    return next.length;
  };

  // --- an explicit clock time: "9h", "09:00", "as 10", "10h30" ---------------
  const hours = new Set();
  let m;
  const explicitRx = /\b(\d{1,2})[:h](\d{2})\b|\b(\d{1,2})\s*h\b|\bas\s+(\d{1,2})\b|\bat\s+(\d{1,2})\b/g;
  while ((m = explicitRx.exec(t)) !== null) {
    const h = Number(m[1] || m[3] || m[4] || m[5]);
    if (h >= 0 && h <= 23) hours.add(h);
  }
  if (hours.size) {
    // Same rule as an unoffered weekday, and it matters more here: with a
    // single slot on offer, "as 14:00 pode ser?" would otherwise fall through
    // to the affirmative branch and book the 09:00 nobody asked for.
    if (!desc.some(x => hours.has(x.hour))) return out('none', null, 'time_not_offered');
    narrow(x => hours.has(x.hour), 'time');
  }

  // --- a weekday name -------------------------------------------------------
  const wanted = new Set();
  for (const [wd, names] of Object.entries(WEEKDAYS)) {
    if (names.some(n => t.includes(n))) wanted.add(Number(wd));
  }
  if (wanted.size) {
    // A weekday we never offered is a NEW request, not a confirmation. C1's
    // preferDate path owns that; booking must keep its hands off it.
    if (!desc.some(x => wanted.has(x.weekday))) return out('none', null, 'weekday_not_offered');
    narrow(x => wanted.has(x.weekday), 'weekday');
  }

  // --- "dia 10", or an explicit 10/09 --------------------------------------
  const dm = t.match(/\b(\d{1,2})[\/\-.](\d{1,2})\b/);
  if (dm) {
    const day = Number(dm[1]), mon = Number(dm[2]);
    if (!desc.some(x => x.day === day && x.month === mon)) return out('none', null, 'date_not_offered');
    narrow(x => x.day === day && x.month === mon, 'date');
  } else {
    const dia = t.match(/\bdia\s+(\d{1,2})\b/);
    if (dia) {
      const day = Number(dia[1]);
      if (!desc.some(x => x.day === day)) return out('none', null, 'date_not_offered');
      narrow(x => x.day === day, 'day_of_month');
    }
  }

  // --- "a primeira", "the last one" ----------------------------------------
  if (pool.length > 1) {
    for (const o of ORDINALS) {
      if (o.rx.test(t)) {
        const target = o.idx === -1 ? desc[desc.length - 1] : desc[o.idx];
        if (target && pool.includes(target)) { pool = [target]; signals.push('ordinal'); }
        break;
      }
    }
  }

  if (signals.length && pool.length === 1) {
    return out('matched', pool[0].slot, signals.join('+'));
  }
  if (signals.length && pool.length > 1) {
    return out('ambiguous', null, signals.join('+'));
  }

  // --- a bare "sim" only works when there is nothing to be ambiguous about ---
  if (AFFIRMATIVE.test(t)) {
    if (desc.length === 1) return out('matched', desc[0].slot, 'affirmative_single_offer');
    return out('ambiguous', null, 'affirmative_multiple_offers');
  }
  return out('none');
}


// The second of the two checks. The first ran before the Claude call so the
// reply would be right; this one runs with nothing between it and the create.
const d   = $('DecideEscalation').first().json;
const cfg = $('AfterLead').first().json.config || {};
const fb  = readFreeBusy($input.first().json, cfg.calendar_id);
const slot = d.bookingSlot;

// A failed re-check is NOT permission to book. readFreeBusy exists because a
// calendar we cannot read answers 200 with an empty busy list, which is
// indistinguishable from "free" -- and here that would mean booking over
// somebody.
let stillFree = false, recheckError = fb.error;
if (fb.ok) {
  stillFree = !fb.busy.some(b =>
    DateTime.fromISO(slot.startUtc) < DateTime.fromISO(b.end) &&
    DateTime.fromISO(slot.endUtc)   > DateTime.fromISO(b.start));
  if (!stillFree) recheckError = 'slot_taken_since_offer';
}
return [{ json: { ...d, stillFree, recheckError } }];

// ============================================================================
// Deterministic language detection for SYSTEM messages — Checkpoint D2.
//
// WHY THIS IS NOT A MODEL CALL
// The handoff note is the message sent when the Concierge cannot answer: the
