   *
   * True only when: the sender is a number this client has CONFIGURED as an
   * agent, AND that number is not already a lead. Anything else — an unknown
   * number, a configured number that is also a lead, a missing config, a
   * failed lookup — continues down the lead path unchanged.
   *
   * The tie-break is deliberate and was specified: if an agent's number is
   * somehow also a lead's number, THE LEAD PATH WINS. A prospect getting no
   * reply is worse than a listing needing to be re-sent.
   *
   * FindExistingLead already sits on this path, so "is it also a lead" costs
   * no extra round trip. Every reference is to a NAMED node, never $json —
   * rule 16: a positional reference survives only until someone inserts a node.
   */
  try {
    const cfg = ($('FlattenClient').first().json.config) || {};
    const nums = ((cfg.listing_ingest || {}).agent_numbers) || [];
    if (!Array.isArray(nums) || nums.length === 0) return false;

    // Digits only, with the international `00` prefix folded away — "00351..."
    // and "+351..." are the same number, and `00` is how most of Europe writes
    // it. Without this an operator configuring the agent number that way would
    // find the branch silently never firing. src/lib/matching/extract.ts had
    // the identical gap, found by a test there.
    const digits = (s) => String(s == null ? '' : s).replace(/\D/g, '').replace(/^00/, '');
    const from = digits($('Normalise').first().json.from);
    if (!from) return false;
    if (!nums.some((n) => digits(n) === from)) return false;

    // A lead lookup that FAILED is not a lookup that found nothing. If we
    // cannot tell, we take the lead path -- the safe direction.
    const res = $('FindExistingLead').first().json;
    const ok = res.statusCode >= 200 && res.statusCode < 300;
    if (!ok) return false;
    const rows = Array.isArray(res.body) ? res.body : [];
    return rows.length === 0;
  } catch (e) {
    return false;
  }
})() }}

