/*
 * Assert the cockpit's response. `neverError: true` on the HTTP node turns a
 * 4xx into a green node with an item (lesson #13), so a non-2xx here would
 * otherwise look exactly like a stored listing.
 */
const res = $input.first().json;
const status = Number(res.statusCode || 0);
const body = res.body || {};
const from = $('Normalise').first().json.from;

if (status < 200 || status >= 300 || body.ok !== true) {
  return [{ json: {
    from,
    ok: false,
    replyText: 'Something went wrong saving that listing. It has not been saved — please try again, or add it in the cockpit.',
    listingError: `cockpit returned ${status}${body.error ? ': ' + body.error : ''}`,
  } }];
}
return [{ json: { from, ok: true, kind: body.kind, replyText: String(body.reply || '') } }];

/*
 * And assert the Twilio response, for the same reason. The agent's
 * confirmation is the only thing telling them their listing landed, so a
 * silent send failure is a listing they believe exists and does not.
 */
const res = $input.first().json;
const status = Number(res.statusCode || 0);
const sent = status >= 200 && status < 300;
const prior = $('AfterListing').first().json;
return [{ json: {
  ...prior,
  agentReplySent: sent,
  agentReplyStatus: status,
  agentReplyError: sent ? null : (res.body && (res.body.message || res.body.error_message)) || 'twilio rejected the send',
} }];

// ============================================================================
// Deterministic language detection for SYSTEM messages — Checkpoint D2.
//
// WHY THIS IS NOT A MODEL CALL
// The handoff note is the message sent when the Concierge cannot answer: the
// model refused, returned unparseable JSON twice, or produced a reply that had
// to be discarded. It is the one message that must still work *when the model
// has failed*, which rules out asking a model — either to write it or to say
// what language to write it in.
//
// So: fixed strings from config, keyed by language, chosen by the rules below.
//
// This is a classifier for THREE known languages on SHORT messages, not a
// general-purpose one. It is allowed to be unsure, and being unsure is safe:
// an undecided result falls back to the client's configured default rather
// than guessing. Sending Portuguese to a Portuguese lead is the win; sending
// Spanish to a Portuguese lead because two words matched is worse than the
// English we send today.
// ============================================================================

// Accented and punctuation marks that occur in ONE of the three languages and
// effectively settle it on their own. Checked before normalisation, because
// stripping diacritics destroys exactly the signal that discriminates pt from
// es -- the two languages that actually get confused.
const HARD_MARKERS = [
  { lang: 'pt', rx: /[ãõ]/, weight: 6 },          // não, mão, então, opções
  { lang: 'pt', rx: /ç/, weight: 5 },             // preço, começar
  { lang: 'es', rx: /ñ/, weight: 6 },             // mañana, año, señor
  { lang: 'es', rx: /[¿¡]/, weight: 6 },          // inverted punctuation
];

// Function words and greetings. Deliberately excludes anything the three share
// (que, para, no, si/sim, por favor, esta) -- a shared word is not evidence.
// Function words. Only DISCRIMINATING tokens: anything the languages share
// (que, para, no, casa, como, por favor) is not evidence and is excluded.
// The pt/es minimal pairs do most of the work here -- com/con, uma/una,
// quando/cuando, muito/mucho -- because those two are the pair that actually
// gets confused.
const WORD_MARKERS = {
  pt: ['nao', 'obrigado', 'obrigada', 'ola', 'voce', 'gostaria', 'queria',
       'muito', 'estou', 'tenho', 'tem', 'quero', 'bom dia', 'boa tarde',
       'boa noite', 'feira', 'imovel', 'imoveis', 'moradia', 'preciso',
       'gostava', 'entao', 'onde', 'com', 'uma', 'um', 'quando', 'quanto',
       'qual', 'mais', 'na', 'nas', 'dos', 'das', 'ate', 'posso', 'pode',
       'procuro', 'visitar', 'marcar', 'falar', 'pessoa', 'afinal', 'mudar'],
  es: ['hola', 'gracias', 'quisiera', 'usted', 'tambien', 'buenos dias',
       'buenas tardes', 'buenas noches', 'vivienda', 'piso', 'necesito',
       'busco', 'con', 'una', 'cuando', 'cuanto', 'donde', 'ahora', 'manana',
       'el', 'los', 'las', 'muy', 'mucho', 'estoy', 'tengo', 'puedo',
       'hablar', 'jueves', 'viernes', 'quiero'],
  en: ['the', 'and', 'you', 'are', 'is', 'would', 'like', 'hello', 'hi',
       'thanks', 'thank', 'please', 'can', 'i', 'im', 'looking', 'house',
       'flat', 'apartment', 'available', 'viewing', 'week', 'time', 'do',
       'have', 'see', 'come', 'speak', 'person', 'anything', 'something'],
};

const SUPPORTED = ['pt', 'en', 'es'];

// detectLanguage(text) -> {lang: 'pt'|'en'|'es'|null, scores, confident}
// Returns null when the evidence is thin or the top two are close. Callers
// must treat null as "use the configured default", never as a language.
function detectLanguage(text) {
  const raw = String(text || '');
  const out = (lang, scores, confident) => ({ lang, scores, confident });
  if (!raw.trim()) return out(null, { pt: 0, en: 0, es: 0 }, false);

  const lower = raw.toLowerCase();
  const scores = { pt: 0, en: 0, es: 0 };

  for (const m of HARD_MARKERS) {
    if (m.rx.test(lower)) scores[m.lang] += m.weight;
  }

  // Normalise for word matching so "voce"/"você" and "manana"/"mañana" both
  // land, having already banked the diacritic evidence above.
  const flat = ' ' + lower.normalize('NFD').replace(/[̀-ͯ]/g, '')
                          .replace(/[^a-z0-9']+/g, ' ').trim() + ' ';
  for (const lang of SUPPORTED) {
    for (const w of WORD_MARKERS[lang]) {
      const needle = w.includes(' ') ? w : ' ' + w + ' ';
      if (flat.includes(needle)) scores[lang] += 2;
    }
  }

  const ranked = SUPPORTED.slice().sort((a, b) => scores[b] - scores[a]);
  const top = ranked[0], second = ranked[1];
  // A single weak hit decides nothing, and a near-tie between pt and es is the
  // case most likely to be wrong. Both fall back rather than guess.
  // Two ways to be sure, and they cover different shapes of message:
  //   - unopposed: any evidence at all for exactly one language, none for the
  //     others. "Ola, procuro casa em Cascais" is short but unambiguous.
  //   - contested: enough evidence AND a clear margin. This is the pt/es case,
  //     where both score and the winner has to actually win.
  // Everything else falls back to the configured default rather than guessing.
  const unopposed = scores[top] >= 2 && scores[second] === 0;
  const contested = scores[top] >= 4 && (scores[top] - scores[second]) >= 4;
  const confident = unopposed || contested;
  return out(confident ? top : null, scores, confident);
}

// pickMessage(messages, lang, fallbackLang) -> string|null
//
// `messages` is the config map, e.g. {pt: '...', en: '...', es: '...'}. Resolution
// order is: detected language -> the client's configured default -> English ->
// whatever single string was configured. Every step is a fixed string; nothing
// here is generated.
function pickMessage(messages, lang, fallbackLang) {
  if (typeof messages === 'string') return messages;          // legacy single string
  if (!messages || typeof messages !== 'object') return null;
  const order = [lang, fallbackLang, 'en', 'pt'];
  for (const k of order) {
    if (k && typeof messages[k] === 'string' && messages[k].trim()) return messages[k];
  }
  const first = Object.values(messages).find(v => typeof v === 'string' && v.trim());
  return first || null;
}

// Convenience: resolve a named system message for a lead's text in one call.
// `cfg` is client_automations.config.
function systemMessage(cfg, name, leadText) {
  const c = cfg || {};
  const det = detectLanguage(leadText);
  const fallback = c.default_language
    || (Array.isArray(c.languages) && c.languages.length ? c.languages[0] : 'en');
  const bag = (c.system_messages || {})[name];
  const picked = pickMessage(bag, det.lang, fallback);
  return {
    text: picked || c.handoff_note || null,
    lang: det.lang || fallback,
    detected: det.lang,
    confident: det.confident,
    scores: det.scores,
  };
}


// ============================================================================
// CatchInternal — the convergence point for every Code node that throws.
//
// See docs/code-node-failure-handling-spec.md. The short version: 0 of 32 Code
// nodes had an error branch, LogRun is a leaf reached at the end of every
// branch, so a throw wrote no automation_runs row and the 30-minute failed-run
// health check could not see it. Lead unanswered, operator unalerted, every
// dashboard green.
//
// THIS NODE MUST NOT THROW. It is the handler; nothing catches the catcher. So
// the whole body is one try/catch whose recovery block does nothing but build a
// literal object, and every reference to another node goes through safeNode(),
// because $('X') throws when X has not executed and half the workflow has not.
//
// It is one of two Code nodes with no error branch of its own, both named in
// tests/workflow-error-branches.test.ts with their reasons. The other is
// ThrowDbOutage, which throws deliberately so the execution is recorded as an
// error rather than a quiet success -- catching it would undo D5's fix.
// ============================================================================

// Which zone a node belongs to is decided by WHAT HAS ALREADY HAPPENED TO THE
// LEAD when it throws. That is the only thing that changes the right response.
const ZONES = {
  // 1 - the lead is not yet identifiable. Nobody to answer; email is the record.
  VerifySignature: 1, Normalise: 1, FlattenClient: 1,
  // 2 - lead known, nothing sent. The handoff note is owed and is still possible.
  AfterLead: 2, AfterListing: 2, AfterAgentReply: 2, MediaReply: 2,
  ProposeSlots: 2, MatchConfirmation: 2, ResolveBooking: 2, BuildClaudeRequest: 2,
  ParseClaude: 2, ParseGuardRetry: 2, DecideEscalation: 2,
  // 3 - the booking path, after the model may already have written a
  //     confirmation. Never book, never let a confirmation stand.
  SkipBooking: 3, ReadRecheck: 3, AfterBooking: 3, BlockedBooking: 3,
  CreatedBooking: 3, ResolveConflict: 3,
  // 4 - the lead already has their reply. Record and continue; NEVER re-send.
  AfterSend: 4, AfterMediaSend: 4, AfterHandoff: 4, AfterNotify: 4,
  AfterEmailAlert: 4, MergeLeadFields: 4, AfterLeadUpdate: 4,
  PrepRunAI: 4, PrepRunDuplicate: 4, PrepRunSilenced: 4, PrepRunMedia: 4,
  PrepRunEscalated: 4,
};

// Hardcoded rather than read from Normalise, because Normalise is one of the
// nodes that can be the thing that threw. It is the same constant Normalise
// carries; if it ever changes, both change.
const SUPABASE_URL = 'https://txxkqskhxhwtrhbmwwig.supabase.co';

function build() {
  // Literal node names, one accessor each. A silent catch is how the first
  // version of this node returned all-nulls and told nobody why, so every
  // failure is recorded in `probe` and travels to the alert.
  //
  // NOTE THE `first(0)`. Without the explicit branch index this returns
  // undefined for every node, and the handler produces an all-null object that
  // looks like "we knew nothing" rather than like a bug. Measured on n8n
  // 2.28.3: an item arriving on an error output carries $prevNode.outputIndex
  // = 1, and that leaks into the DEFAULT branch index for every $() lookup, so
  // $('AfterLead').all() asks for AfterLead's output 1 -- which does not exist
  // -- and returns []. all(0) returns the item. Every accessor in this node
  // therefore names its branch.
  const probe = [];
  const safe = (label, fn) => {
    try {
      const v = fn();
      if (!v) { probe.push(label + '=empty'); return null; }
      return v;
    } catch (e) {
      probe.push(label + '=' + String(e && e.message ? e.message : e).slice(0, 60));
      return null;
    }
  };

  // $prevNode is the node that handed us this item -- on an error branch, the
  // node that threw. This is how the alert names a node instead of saying
  // "something threw", which is not actionable.
  //
  // Measured against n8n 2.28.3 in a throwaway container rather than read off
  // the source: reading workflow-execute.js suggested a thrown node sends its
  // INPUT items down output 0, which would have made every branch here useless
  // and passed junk down the happy path. A real run says otherwise -- the item
  // arrives on output 1 as {error: '<message> [line N]'}, $prevNode.name is the
  // node that threw, and $prevNode.outputIndex is 1. The success branch does
  // not run at all.
  let failedNode = 'unknown', fromErrorOutput = null;
  try { failedNode = $prevNode.name || 'unknown'; } catch (e) { failedNode = 'unknown'; }
  try { fromErrorOutput = $prevNode.outputIndex === 1; } catch (e) { fromErrorOutput = null; }
  const zone = ZONES[failedNode] || 2;   // unknown node: assume the lead is owed a reply

  // n8n puts the thrown message on the item. Take it if it is there -- "a Code
  // node threw" is not an actionable alert and the message usually names the
  // line. Never trust its shape.
  let thrown = null;
  try {
    const it = $input.first().json;
    if (it && typeof it.error === 'string') thrown = it.error.slice(0, 300);
  } catch (e) { thrown = null; }

  // Zone 1's email is the ONLY record there will be, so it has to carry what
  // arrived. Read from the Webhook itself, which is the one node guaranteed to
  // have run -- Normalise, the usual source, is one of the nodes that can be
  // the thing that threw.
  const hook = safe('Webhook', () => $('Webhook').first(0).json);
  const raw = (hook && hook.body) || {};

  const norm = safe('Normalise', () => $('Normalise').first(0).json);
  const flat = safe('FlattenClient', () => $('FlattenClient').first(0).json);
  const lead = safe('AfterLead', () => $('AfterLead').first(0).json);
  const ctx  = lead || flat || norm || {};

  const cfg = (ctx.config) || (flat && flat.config) || {};
  const leadText = ctx.body || (norm && norm.body) || '';

  // The handoff note is a FIXED CONFIG STRING chosen by deterministic language
  // rules -- no model, no calendar, no network. That is the whole reason it can
  // be the answer when something upstream has broken.
  let note = null, lang = null;
  try {
    const picked = systemMessage(cfg, 'handoff', leadText);
    note = picked.text; lang = picked.lang;
  } catch (e) { note = cfg.handoff_note || null; lang = cfg.default_language || null; }

  // Found by the Zone 4 drill, not by design. AfterSend, AfterMediaSend and
  // AfterHandoff each sit BETWEEN a send and its store. If one throws, the
  // message has already gone to the lead and is never written to `messages` --
  // so LoadHistory feeds the model a conversation in which the assistant never
  // spoke, and the next reply is composed as if it had not. That is the D3
  // LoadHistory defect's shape, reached a different way.
  //
  // DECIDED, 2026-09-08: the handler does NOT write the message row, and this
  // is not an oversight waiting to be improved.
  //
  // `messages` already has one writer per path; a second one racing it can
  // duplicate a turn. The tiebreaker is where each failure lands:
  //
  //   a DUPLICATED turn  -> the lead is sent something twice. It reaches the
  //                         prospect, and nobody can take it back.
  //   a MISSING turn     -> the model composes as if it had not spoken, and
  //                         the alert below reproduces the text, so a human
  //                         can see exactly what the lead was told and act.
  //
  // Prefer the failure that lands where someone can act on it. The alert
  // reproduces the reply for the same reason EmailDbOutage reproduces the
  // inbound message: it exists nowhere else.
  const POST_SEND = { AfterSend: 'SendWhatsApp', AfterMediaSend: 'SendMediaReply',
                      AfterHandoff: 'SendHandoffNote' };
  let unrecordedReply = null;
  if (POST_SEND[failedNode]) {
    const r = failedNode === 'AfterSend'
      ? safe('SendWhatsApp', () => $('SendWhatsApp').first(0).json)
      : failedNode === 'AfterMediaSend'
        ? safe('SendMediaReply', () => $('SendMediaReply').first(0).json)
        : safe('SendHandoffNote', () => $('SendHandoffNote').first(0).json);
    const b = (r && r.body) || {};
    unrecordedReply = {
      sid: b.sid || null,
      status: r ? r.statusCode : null,
      text: b.body || null,
    };
  }

  // Zone 3 only: an event may already exist for this slot, created before the
  // throw. The operator has to be told to look, because nothing else will.
  let slotWarning = null;
  if (zone === 3) {
    const mc = safe('MatchConfirmation', () => $('MatchConfirmation').first(0).json) || {};
    const s = mc.bookingSlot || null;
    if (s) {
      slotWarning = 'A calendar event MAY have been created for '
        + (s.startLocal || s.startUtc) + ' (id ' + (mc.bookingEventId || 'unknown')
        + '). Check the calendar before replying to this lead.';
    }
  }

  const phone = ctx.from || (norm && norm.from) || null;
  // canReply stays false for zone 1 even though `raw.From` gives us a number:
  // without a resolved client there is no configured handoff note to send, and
  // a message we invent is exactly what this project does not do.
  const canReply = (zone === 2 || zone === 3) && !!phone && !!note;

  return {
    internalFailure: true,
    failedNode, zone,
    errorType: 'internal_error:' + failedNode,
    errorMessage: thrown || 'a Code node threw; the message did not reach the handler',
    fromErrorOutput,
    // Everything the downstream nodes need, flattened, so none of them has to
    // reach back into a node that may not have run.
    supabaseUrl: SUPABASE_URL,
    clientAutomationId: ctx.clientAutomationId || (flat && flat.clientAutomationId) || null,
    clientId: ctx.clientId || (flat && flat.clientId) || null,
    leadId: ctx.leadId || null,
    from: phone || String(raw.From || '').replace(/^whatsapp:/, '') || null,
    profileName: ctx.profileName || (norm && norm.profileName) || raw.ProfileName || null,
    messageSid: ctx.messageSid || (norm && norm.messageSid) || raw.MessageSid || null,
    body: leadText || raw.Body || '',
    handoffBody: note,
    handoffLang: lang,
    canReply,
    slotWarning,
    priorQualification: ctx.priorQualification || null,
    probe: probe.join(' ; ') || 'all context nodes read cleanly',
    unrecordedReply,
    startedAt: ctx.startedAt || new Date().toISOString(),
    at: new Date().toISOString(),
  };
}

let out;
try {
  out = build();
} catch (e) {
  // The recovery block constructs a literal and nothing else. If this is ever
  // reached, the email downstream is the only record there will be, so it
  // carries the reason this node could not do its job.
  out = {
    internalFailure: true, failedNode: 'unknown', zone: 1,
    errorType: 'internal_error:CatchInternal',
    errorMessage: 'the failure handler itself failed: ' + (e && e.message ? e.message : 'unknown'),
    supabaseUrl: SUPABASE_URL,
    clientAutomationId: null, clientId: null, leadId: null,
    from: null, profileName: null, messageSid: null, body: '',
    handoffBody: null, handoffLang: null, canReply: false, slotWarning: null,
    priorQualification: null,
    startedAt: new Date().toISOString(), at: new Date().toISOString(),
  };
}
return [{ json: out }];

// ============================================================================
// Is the booking we stored still real? — shared source.
//
// Embedded verbatim into ResolveBooking. Unit-tested standalone in
// tests/booking_check.test.js, which loads THIS file rather than a copy.
//
// WHY THIS EXISTS
// On 2026-09-11 a lead was told, on every message for an hour, that a first
// meeting was already booked -- so the model never offered times, and the
// stage sat at viewing_booked while the lead was being re-qualified. The
// booking had been created on 5 September and was genuine (Google returned
// the event). By the rehearsal the slot was in the past and the event was no
// longer in the calendar. Nothing had looked at it since the day it was made.
//
// THE RULE
// A stored booking is a CLAIM about the calendar. Before the model is told an
// appointment exists, the claim is checked against the calendar, and against
// the clock. Three outcomes retire it -- the slot has passed, Google says the
// event is cancelled, or Google says it is gone -- and one keeps it with a
// warning: the calendar could not be read. That last case is stated to the
// operator as an event, not only to the model in the prompt, because a Google
// outage that silently changes booking behaviour is the silent-failure
// pattern this project keeps hitting.
//
// The bias, when unsure, is to KEEP the booking and say so. Retiring a real
// booking because of a transient 503 would let the model offer a second
// appointment on top of a first one that still exists.
// ============================================================================

// resolveBookingCheck(existing, httpResponse, nowMs, opts) ->
//   { check, retire, error, googleStatus }
//
//   existing      the stored booking: { event_id, startUtc, endUtc, ... }
//   httpResponse  the events.get envelope { statusCode, body } or null
//   nowMs         the clock, injected so the tests can move it
//   opts.calendarReadable
//                 whether free/busy on the SAME calendar succeeded this turn.
//                 Google answers 404 both for an event that was purged and for
//                 a calendar id that is wrong, and only one of those means the
//                 booking is gone. If the calendar could not be read either,
//                 a 404 is a read failure, not a missing event.
//
//   check   'past' | 'cancelled' | 'missing' | 'confirmed' | 'unreadable'
//   retire  true when the booking must stop being asserted
//   error   a short reason string for 'unreadable', else null
function resolveBookingCheck(existing, httpResponse, nowMs, opts) {
  const eb = existing || {};
  const calendarReadable = !(opts && opts.calendarReadable === false);
  const res = httpResponse || {};
  const code = typeof res.statusCode === 'number' ? res.statusCode : null;
  const body = res.body || {};

  // The clock wins over the calendar: a slot that has ended is not upcoming
  // whatever Google says about it, and it needs no Google to say so.
  const endMs = Date.parse(eb.endUtc || eb.startUtc || '');
  if (Number.isFinite(endMs) && endMs <= nowMs) {
    return { check: 'past', retire: true, error: null, googleStatus: code };
  }

  if (code !== null && code >= 200 && code < 300) {
    if (body.status === 'cancelled') {
      return { check: 'cancelled', retire: true, error: null, googleStatus: code };
    }
    return { check: 'confirmed', retire: false, error: null, googleStatus: code };
  }
  if ((code === 404 || code === 410) && calendarReadable) {
    return { check: 'missing', retire: true, error: null, googleStatus: code };
  }
  if (code === 404 || code === 410) {
    return { check: 'unreadable', retire: false,
             error: 'events_get_http_' + code + ':calendar_unreadable', googleStatus: code };
  }
  const msg = body.error && body.error.message ? ':' + String(body.error.message).slice(0, 120) : '';
  return { check: 'unreadable', retire: false,
           error: 'events_get_http_' + (code === null ? 'none' : code) + msg,
           googleStatus: code };
}


// Convergence point: reached from HasExistingBooking's false branch carrying the
// MatchConfirmation item, or from VerifyBooking carrying Google's response. The
// input's shape is NOT used to tell which -- MatchConfirmation is read by name
// and the stored intent decides (lesson 12).
const p = $('MatchConfirmation').first().json;
const out = { ...p, bookingCheck: 'none', bookingRetired: null, bookingUnreadable: false,
              bookingCheckStatus: null, bookingCheckError: null };
const eb = p.existingBooking || null;

if (p.bookingIntent === 'already_booked' && eb) {
  const res = $input.first().json || {};
  // Free/busy on the same calendar ran upstream this turn; if it failed, a 404
  // here is a read failure, not a purged event.
  const calendarReadable = !($('ProposeSlots').first().json.slotError);
  const r = resolveBookingCheck(eb, res, Date.now(), { calendarReadable });
  out.bookingCheck = r.check;
  out.bookingCheckStatus = r.googleStatus;
  out.bookingCheckError = r.error;
  out.bookingUnreadable = r.check === 'unreadable';
  if (r.retire) {
    // The claim is withdrawn HERE, before the model is told anything, and
    // MergeLeadFields archives it on the lead later in the same run. Slots
    // were already proposed upstream from live free/busy, so if the lead
    // wants a new time the offer is real.
    out.bookingIntent = 'none';
    out.bookingSlot = null;
    out.bookingEventId = null;
    out.existingBooking = null;
    out.bookingRetired = Object.assign({}, eb, {
      retired_reason: r.check, retired_at: new Date().toISOString(), google_status: r.googleStatus });
  }
}
return [{ json: out }];
